const lessons = [
  {"num": 2, "time": "00:00:30,000 --> 00:00:35,640", "arabic": "مَا كُنْتُ أَظُنُّ أَنَّكَ سَتَعُودُ مَرَّةً أُخْرَى لِهَذَا السِّجْنِ", "segs": null, "full_uz": "Bu zindonga yana qaytishingni kutmagandim.", "note": null},
  {"num": 3, "time": "00:00:35,640 --> 00:00:40,700", "arabic": "كُنْتُ عَلَى يَقِينٍ بِأَنَّكَ سَتَلْقَى مَصِيرَ رِفَاقِكَ", "segs": null, "full_uz": "Do'stlaring taqdiriga duchor bo'lishingga amin edim.", "note": null},
  {"num": 4, "time": "00:00:40,700 --> 00:00:43,840", "arabic": "هُمْ لَيْسُوا بِرِفَاقِي", "segs": null, "full_uz": "Ular mening do'stlarim emas.", "note": null},
  {"num": 5, "time": "00:00:43,840 --> 00:00:51,579", "arabic": "وَمَا أَنَا مَوْجُودٌ هُنَا إِلَّا إِثْرَ وِشَايَةٍ مِنْ رَجُلٍ كَاذِبٍ لَا يَخَافُ اللَّهَ", "segs": [{"ar": "وَمَا أَنَا مَوْجُودٌ هُنَا إِلَّا إِثْرَ وِشَايَةٍ", "uz": "men bu yerda faqat bir tuhmat tufayli turibman"}, {"ar": "مِنْ رَجُلٍ كَاذِبٍ لَا يَخَافُ اللَّهَ", "uz": "Allohdan qo'rqmaydigan yolg'onchi bir kishining"}], "full_uz": "Men bu yerda faqat Allohdan qo'rqmaydigan yolg'onchi bir kishining tuhmati tufayli turibman.", "note": null},
  {"num": 6, "time": "00:00:51,579 --> 00:00:57,039", "arabic": "اَلْمُهِمُّ الْآنَ أَنَّكَ بِخَيْرٍ", "segs": null, "full_uz": "Muhimi, hozir sen sog'-salomatsan.", "note": null},
  {"num": 7, "time": "00:00:57,039 --> 00:01:00,460", "arabic": "وَدُونَ أَنْ يُنْزِلَ بِكَ أَمِيرُ الْمُؤْمِنِينَ عُقُوبَةً", "segs": null, "full_uz": "Va mo'minlar amiri senga biror jazo bermay turib.", "note": null},
  {"num": 8, "time": "00:01:00,460 --> 00:01:03,179", "arabic": "فَأَظُنُّ وَالْعِلْمُ عِنْدَ اللَّهِ", "segs": null, "full_uz": "Shunday deb o'ylayman, aslida ilm Alloh huzurida.", "note": null},
  {"num": 9, "time": "00:01:03,179 --> 00:01:07,620", "arabic": "أَنَّهُ سَيَرْأَفُ بِحَالِكَ وَحَالِ مَنْ مَعَكَ", "segs": null, "full_uz": "U sening va sen bilan birga bo'lganlarning holiga rahm qiladi.", "note": null},
  {"num": 10, "time": "00:01:07,620 --> 00:01:11,439", "arabic": "سَأَعُودُ إِلَيْكَ لَيْلًا", "segs": null, "full_uz": "Kechqurun yoningga qaytaman.", "note": null},
  {"num": 11, "time": "00:01:11,439 --> 00:01:13,460", "arabic": "لِتُخْبِرَنِي بِكُلِّ مَا حَدَثَ مَعَكَ", "segs": null, "full_uz": "Sen bilan bo'lgan hamma narsani menga aytib berishing uchun.", "note": null},
  {"num": 12, "time": "00:01:27,040 --> 00:01:31,280", "arabic": "وَمَنْ قَالَ لَكَ أَنِّي أُرِيدُ بَيْعَ دُكَّانِي؟", "segs": null, "full_uz": "Do'konimni sotmoqchiman deb senga kim aytdi?", "note": null},
  {"num": 13, "time": "00:01:31,280 --> 00:01:32,060", "arabic": "يَا أَبَا عَبْدِ اللَّهِ", "segs": null, "full_uz": "Ey Abu Abdulloh.", "note": null},
  {"num": 14, "time": "00:01:32,060 --> 00:01:36,080", "arabic": "أَنْتَ تَرَى أَنَّ هَذِهِ الدُّكَّانَةَ لَا تَدُرُّ عَلَيْكَ إِلَّا الْقَلِيلَ مِنَ الْمَالِ", "segs": null, "full_uz": "Ko'rib turibsizki, bu do'kon sizga faqat oz pul keltiradi.", "note": null},
  {"num": 15, "time": "00:01:36,080 --> 00:01:39,800", "arabic": "فَلَوْ أَنَّكَ بِعْتَهَا وَاسْتَفَدْتَ مِنْ ثَمَنِهَا فِي عَمَلٍ آخَرَ", "segs": null, "full_uz": "Agar uni sotib, pulidan boshqa ishga foydalansangiz.", "note": null},
  {"num": 16, "time": "00:01:39,800 --> 00:01:42,240", "arabic": "لَكَانَ فِي ذَلِكَ مَغْنَمًا لَكَ وَلِغَيْرِكَ", "segs": null, "full_uz": "Bu sizga ham, boshqalarga ham foyda keltirardi.", "note": null},
  {"num": 17, "time": "00:01:42,240 --> 00:01:44,219", "arabic": "مَنْ تَقْصِدُ بِغَيْرِي؟", "segs": null, "full_uz": "Mendan boshqa deganda kimni nazarda tutyapsan?", "note": null},
  {"num": 18, "time": "00:01:44,219 --> 00:01:46,320", "arabic": "أَنْتَ أَمْ مَنْ أَرْسَلَكَ لِيَشْتَرِيَهَا؟", "segs": null, "full_uz": "Senmi yoki seni uni sotib olish uchun yuborgan kishimi?", "note": null},
  {"num": 19, "time": "00:01:46,320 --> 00:01:48,600", "arabic": "أَنَا أَنَا أَنَا مَا شَأْنِي بِهَذَا كُلِّهِ؟", "segs": null, "full_uz": "Men, men, men... bularning menga qanday aloqasi bor?", "note": null},
  {"num": 20, "time": "00:01:48,600 --> 00:01:50,900", "arabic": "مَا الَّذِي سَأَجْنِيهِ مِنْ وَرَاءِ ذَلِكَ؟", "segs": null, "full_uz": "Bundan menga nima foyda?", "note": null},
  {"num": 21, "time": "00:01:50,900 --> 00:01:53,320", "arabic": "أَنَا يَا أَبَا عَبْدِ اللَّهِ لَا أُرِيدُ لَكَ إِلَّا الْخَيْرَ", "segs": null, "full_uz": "Men, ey Abu Abdulloh, senga faqat yaxshilik istayman.", "note": null},
  {"num": 22, "time": "00:01:53,320 --> 00:01:56,520", "arabic": "أَمْ تَظُنُّ أَنَّنِي سِمْسَارٌ بَيْنَكَ وَبَيْنَ الْمُشْتَرِي؟", "segs": null, "full_uz": "Yoki men sen bilan xaridor orasida vositachi deb o'ylaysanmi?", "note": null},
  {"num": 23, "time": "00:01:56,519 --> 00:02:04,340", "arabic": "لَا أَدْرِي عَنْكَ يَا عَامِرُ، وَلَكِنَّ الَّذِي أَعْلَمُهُ وَيَجِبُ أَنْ تَعْلَمَهُ أَنَّنِي لَنْ أَبِيعَ دُكَّانِي لَا مِنْ أَجْلِكَ وَلَا مِنْ أَجْلِ غَيْرِكَ", "segs": [{"ar": "لَا أَدْرِي عَنْكَ يَا عَامِرُ", "uz": "sen haqingda bilmayman, Omir"}, {"ar": "وَلَكِنَّ الَّذِي أَعْلَمُهُ وَيَجِبُ أَنْ تَعْلَمَهُ", "uz": "lekin men bilgan va sen ham bilishing kerak bo'lgan narsa"}, {"ar": "أَنَّنِي لَنْ أَبِيعَ دُكَّانِي لَا مِنْ أَجْلِكَ وَلَا مِنْ أَجْلِ غَيْرِكَ", "uz": "do'konimni na sen, na boshqa hech kim uchun sotmasligim"}], "full_uz": "Sen haqingda bilmayman, Omir, lekin men bilgan va sen ham bilishing kerak bo'lgan narsa shuki, men do'konimni na sen, na boshqa hech kim uchun sotmayman.", "note": null},
  {"num": 24, "time": "00:02:04,340 --> 00:02:12,460", "arabic": "يَا أَبَا عَبْدِ اللَّهِ، وَلَكِنَّ الرَّجُلَ سَيَدْفَعُ لَكَ مَالًا كَثِيرًا", "segs": null, "full_uz": "Ey Abu Abdulloh, lekin u kishi senga ko'p pul to'laydi.", "note": null},
  {"num": 25, "time": "00:02:12,460 --> 00:02:13,519", "arabic": "أَيُّ رَجُلٍ؟", "segs": null, "full_uz": "Qaysi kishi?", "note": null},
  {"num": 26, "time": "00:02:14,659 --> 00:02:17,840", "arabic": "أَنَا أَقْصِدُ، سَمِعْتُ أَنَّ الرَّجُلَ سَيَدْفَعُ فِيهَا ذَلِكَ", "segs": null, "full_uz": "Demoqchimanki... eshitishimcha, o'sha kishi buning uchun shuncha to'laydi.", "note": null},
  {"num": 27, "time": "00:02:17,840 --> 00:02:21,519", "arabic": "اَلدُّكَّانُ لَيْسَتْ لِلْبَيْعِ يَا عَامِرُ، لَيْسَتْ لِلْبَيْعِ", "segs": null, "full_uz": "Do'kon sotuvga emas, Omir, sotuvga emas.", "note": null},
  {"num": 28, "time": "00:02:22,199 --> 00:02:23,840", "arabic": "اِسْتَوْدَعَكَ اللَّهُ", "segs": null, "full_uz": "Allohga omonat qildim.", "note": "Xayrlashuvda ishlatiladigan an'anaviy ibora."},
  {"num": 29, "time": "00:02:23,840 --> 00:02:26,180", "arabic": "اَلسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ", "segs": null, "full_uz": "Sizga salom, Allohning rahmati va barakoti bo'lsin.", "note": null},
  {"num": 30, "time": "00:02:26,180 --> 00:02:30,480", "arabic": "اَلْحَمْدُ لِلَّهِ الْحَمْدُ لِلَّهِ كَادَ أَنْ يَفْتَضِحَ أَمْرِي", "segs": null, "full_uz": "Hamdlar bo'lsin, hamdlar bo'lsin, sirim fosh bo'lay dedi.", "note": null},
  {"num": 31, "time": "00:02:30,480 --> 00:02:34,879", "arabic": "مَا الَّذِي يَضِيرُكَ يَا ابْنَ حَنْبَلٍ لَوْ تَرَكْتَنَا نَنْتَفِعُ بِخَمْسِينَ دِرْهَمًا", "segs": null, "full_uz": "Bizga ellik dirhamdan foydalanishga yo'l qo'ysang, senga qanday zarar bor, Ibn Hanbal?", "note": null},
  {"num": 32, "time": "00:02:34,879 --> 00:02:36,860", "arabic": "خَمْسِينَ دِرْهَمًا يَا ابْنَ حَنْبَلٍ", "segs": null, "full_uz": "Ellik dirham-a, Ibn Hanbal.", "note": null},
  {"num": 33, "time": "00:02:36,860 --> 00:02:39,500", "arabic": "رَأْسُهُ يَابِسٌ رَأْسُهُ يَابِسٌ", "segs": null, "full_uz": "Boshi qotib qolgan, boshi qotib qolgan.", "note": "«رَأْسُهُ يَابِسٌ» — o'jar, gapga kirmaydigan kishi haqida ishlatiladigan ibora."},
  {"num": 45, "time": "00:03:37,120 --> 00:03:45,739", "arabic": "وَلَكِنْ بَذَلْتُ مَا بِوُسْعِي يَا سَيِّدِي", "segs": null, "full_uz": "Lekin qo'limdan kelganini qildim, xo'jayinim.", "note": null},
  {"num": 46, "time": "00:03:45,739 --> 00:03:49,739", "arabic": "لَوْ أَنَّكَ بَذَلْتَ مَا بِوُسْعِكَ", "segs": null, "full_uz": "Agar sen qo'lingdan kelganini qilganingda.", "note": null},
  {"num": 47, "time": "00:03:49,740 --> 00:03:51,439", "arabic": "لَحَصَلْتَ عَلَى مُوَافَقَتِهِ", "segs": null, "full_uz": "Uning roziligini olgan bo'lardingiz.", "note": null},
  {"num": 48, "time": "00:03:51,439 --> 00:03:55,500", "arabic": "وَلَكِنِّي أَحْسَبُكَ رَمَيْتَ الْكَلَامَ دُونَ حَمَاسٍ وَعَزْمٍ", "segs": null, "full_uz": "Lekin menimcha, gapni ishtiyoq va qat'iyatsiz aytding.", "note": null},
  {"num": 49, "time": "00:03:55,500 --> 00:03:58,980", "arabic": "يَبْدُو أَنَّكَ لَسْتَ بِحَاجَةٍ لِلْمِئَةِ دِرْهَمٍ", "segs": null, "full_uz": "Ko'rinishidan, senga yuz dirham kerak emas.", "note": null},
  {"num": 50, "time": "00:03:58,980 --> 00:04:01,900", "arabic": "لَحْظَةً", "segs": null, "full_uz": "Bir lahza.", "note": null},
  {"num": 51, "time": "00:04:01,900 --> 00:04:03,159", "arabic": "مِئَةُ دِرْهَمٍ؟", "segs": null, "full_uz": "Yuz dirham?", "note": null},
  {"num": 52, "time": "00:04:03,159 --> 00:04:04,060", "arabic": "قُلْتَ لِي خَمْسُونَ", "segs": null, "full_uz": "Menga ellik deganding.", "note": null},
  {"num": 53, "time": "00:04:04,060 --> 00:04:07,600", "arabic": "بَلْ مِئَةُ دِرْهَمٍ إِنِ اسْتَطَعْتَ إِقْنَاعَهَا", "segs": null, "full_uz": "Yo'q, agar uni ko'ndira olsang, yuz dirham.", "note": null},
  {"num": 54, "time": "00:04:07,600 --> 00:04:09,500", "arabic": "مِئَةُ دِرْهَمٍ؟", "segs": null, "full_uz": "Yuz dirham?", "note": null},
  {"num": 55, "time": "00:04:09,500 --> 00:04:11,240", "arabic": "يَا وَيْحَ عَامِرٍ إِنْ لَمْ يُعَاوِدْ", "segs": null, "full_uz": "Agar Omir yana urinib ko'rmasa, unga voy!", "note": null},
  {"num": 56, "time": "00:04:11,240 --> 00:04:13,200", "arabic": "سَأُحَاوِلُ مَرَّةً أُخْرَى", "segs": null, "full_uz": "Yana bir bor urinib ko'raman.", "note": null},
  {"num": 57, "time": "00:04:13,200 --> 00:04:15,000", "arabic": "وَلَوْ أَدَّى ذَلِكَ إِلَى طَرْدٍ مِنَ الدُّكَّانِ", "segs": null, "full_uz": "Hatto bu do'kondan haydalishga olib kelsa ham.", "note": null},
  {"num": 58, "time": "00:04:15,000 --> 00:04:19,400", "arabic": "خَطَرَتْ لِي فِكْرَةٌ", "segs": null, "full_uz": "Xayolimga bir fikr keldi.", "note": null},
  {"num": 59, "time": "00:04:19,399 --> 00:04:22,399", "arabic": "سَتَقْتُلُهُ؟", "segs": null, "full_uz": "Uni o'ldirasanmi?", "note": null},
  {"num": 60, "time": "00:04:22,399 --> 00:04:23,419", "arabic": "أَيُّهَا الْأَحْمَقُ", "segs": null, "full_uz": "Ey ahmoq.", "note": null},
  {"num": 61, "time": "00:04:23,419 --> 00:04:27,239", "arabic": "أَقْتُلُ رَجُلًا مِنْ أَجْلِ دُكَّانٍ يَعْمَلُ فِيهِ إِسْكَافِيٌّ؟", "segs": null, "full_uz": "Etikdo'z ishlaydigan do'kon uchun odam o'ldiramanmi?", "note": null},
  {"num": 62, "time": "00:04:27,239 --> 00:04:31,519", "arabic": "اَلْحَمْدُ لِلَّهِ، حَسِبْتُ أَنَّ شَيْطَانًا قَدْ زَيَّنَ لَكَ ذَلِكَ", "segs": null, "full_uz": "Hamdlar bo'lsin, men buni senga bir shayton chiroyli qilib ko'rsatgan deb o'yladim.", "note": null},
  {"num": 63, "time": "00:04:31,519 --> 00:04:38,359", "arabic": "قُلْ لَهُ أَنَّكَ سَتَتْرُكُ الدُّكَّانَ", "segs": null, "full_uz": "Unga do'konni tark etishingni ayt.", "note": null},
  {"num": 64, "time": "00:04:38,359 --> 00:04:41,879", "arabic": "وَعِنْدَهَا سَيُفْرِغُ دُكَّانَهُ وَيَشْتَغِلُ بِهِ", "segs": null, "full_uz": "Shunda u do'konini bo'shatib, u bilan shug'ullanadi.", "note": null},
  {"num": 65, "time": "00:04:41,879 --> 00:04:44,039", "arabic": "أَتْرُكُ الدُّكَّانَ؟ مَاذَا تَقُولُ؟ أَيْنَ أَذْهَبُ؟", "segs": null, "full_uz": "Do'konni tark etamanmi? Nima deyapsan? Qayerga boraman?", "note": null},
  {"num": 67, "time": "00:04:45,120 --> 00:04:47,459", "arabic": "مُجَرَّدُ قَوْلٍ فَقَطْ", "segs": null, "full_uz": "Shunchaki gap, xolos.", "note": null},
  {"num": 68, "time": "00:04:47,459 --> 00:04:49,459", "arabic": "أَخْشَى، أَخْشَى", "segs": null, "full_uz": "Qo'rqaman, qo'rqaman.", "note": null},
  {"num": 69, "time": "00:04:49,459 --> 00:04:52,459", "arabic": "أَخْشَى، أَخْشَى، أَخْشَى", "segs": null, "full_uz": "Qo'rqaman, qo'rqaman, qo'rqaman.", "note": null},
  {"num": 70, "time": "00:04:52,459 --> 00:04:56,459", "arabic": "يَبْدُو أَنَّكَ لَسْتَ مُتَحَمِّسًا لِلْمِئَةِ دِرْهَمٍ فِيمَا أَرَى", "segs": null, "full_uz": "Ko'rib turibman, yuz dirhamga unchalik qiziqmayapsan.", "note": null},
  {"num": 71, "time": "00:04:56,459 --> 00:04:58,459", "arabic": "مُتَحَمِّسٌ، مُتَحَمِّسٌ جِدًّا", "segs": null, "full_uz": "Qiziqaman, juda ham qiziqaman.", "note": null},
  {"num": 72, "time": "00:04:58,459 --> 00:05:01,459", "arabic": "سَأَقُولُ لَهُ ذَلِكَ كَمَا تُرِيدُ، كَمَا تُرِيدُ", "segs": null, "full_uz": "Senga yoqqanidek unga aytaman, aytaman.", "note": null},
  {"num": 73, "time": "00:05:04,459 --> 00:05:06,459", "arabic": "سَأَرَى", "segs": null, "full_uz": "Ko'raman.", "note": null},
  {"num": 74, "time": "00:05:07,459 --> 00:05:09,459", "arabic": "سَتَرَى", "segs": null, "full_uz": "Ko'rasan.", "note": null},
  {"num": 75, "time": "00:05:12,459 --> 00:05:15,459", "arabic": "مِئَةُ دِرْهَمٍ، مِئَةُ دِرْهَمٍ، يَقُولُ لِي مِئَةً", "segs": null, "full_uz": "Yuz dirham, yuz dirham, menga yuz deyapti.", "note": null},
  {"num": 76, "time": "00:05:17,459 --> 00:05:18,199", "arabic": "اِسْمَعْ يَا قَاسِمُ", "segs": null, "full_uz": "Eshit, Qosim.", "note": null},
  {"num": 77, "time": "00:05:18,199 --> 00:05:22,139", "arabic": "هَذِهِ الْمَهَمَّةُ لَوْ كُشِفَتْ فَفِيهَا هَلَاكُكَ", "segs": null, "full_uz": "Bu topshiriq fosh bo'lsa, unda sening halokating bor.", "note": null},
  {"num": 78, "time": "00:05:22,139 --> 00:05:28,599", "arabic": "وَإِنْ وُفِّقْتَ فِيهَا جَاءَكَ مِنَ الْخَيْرِ مَا لَمْ تَحْلُمْ بِهِ لَا أَنْتَ وَلَا عَشِيرَتُكَ", "segs": [{"ar": "وَإِنْ وُفِّقْتَ فِيهَا", "uz": "agar unda muvaffaqiyatga erishsang"}, {"ar": "جَاءَكَ مِنَ الْخَيْرِ مَا لَمْ تَحْلُمْ بِهِ لَا أَنْتَ وَلَا عَشِيرَتُكَ", "uz": "senga na o'zing, na urug'ing tush ko'rmagan yaxshilik keladi"}], "full_uz": "Agar unda muvaffaqiyatga erishsang, senga na o'zing, na urug'ing tush ko'rmagan yaxshilik keladi.", "note": null},
  {"num": 79, "time": "00:05:28,599 --> 00:05:31,939", "arabic": "أَرْجُو أَنْ أَكُونَ عِنْدَ حُسْنِ ظَنِّكَ بِي يَا مَوْلَايَ", "segs": null, "full_uz": "Umid qilamanki, menga bo'lgan yaxshi fikringizga loyiq bo'laman, xo'jayinim.", "note": null},
  {"num": 80, "time": "00:05:31,939 --> 00:05:44,279", "arabic": "أُرِيدُ أَنْ أَعْرِفَ كُلَّ صَغِيرَةٍ وَكَبِيرَةٍ يَا قَاسِمُ", "segs": null, "full_uz": "Har bir mayda-chuyda va katta narsani bilishni istayman, Qosim.", "note": null},
  {"num": 81, "time": "00:05:44,279 --> 00:05:45,500", "arabic": "أَمْرُكَ يَا مَوْلَايَ", "segs": null, "full_uz": "Xo'p bo'ladi, xo'jayinim.", "note": null},
  {"num": 82, "time": "00:05:45,500 --> 00:05:46,859", "arabic": "اِذْهَبِ الْآنَ", "segs": null, "full_uz": "Hozir bor.", "note": null},
  {"num": 83, "time": "00:05:47,459 --> 00:05:50,419", "arabic": "وَاحْرِصْ عَلَى أَنْ يَظَلَّ مَا اتَّفَقْنَا عَلَيْهِ طَيَّ الْكِتْمَانِ", "segs": null, "full_uz": "Kelishganimiz sir saqlanishiga e'tibor ber.", "note": null},
  {"num": 84, "time": "00:05:50,419 --> 00:05:52,939", "arabic": "وَاحْذَرْ أَنْ يَكْشِفَكَ أَحَدٌ", "segs": null, "full_uz": "Va hech kim seni fosh qilib qo'ymasin, ehtiyot bo'l.", "note": null},
  {"num": 85, "time": "00:05:52,939 --> 00:05:54,620", "arabic": "أَمْرُكَ يَا مَوْلَايَ", "segs": null, "full_uz": "Xo'p bo'ladi, xo'jayinim.", "note": null},
  {"num": 86, "time": "00:05:54,620 --> 00:06:11,719", "arabic": "جَعْفَرٌ الْبَرْمَكِيُّ يَسْتَغِلُّ قُرْبَهُ مِنْكَ فِي كُلِّ شَيْءٍ يَفْعَلُهُ", "segs": null, "full_uz": "Ja'far Barmakiy sizga yaqinligidan qilayotgan har bir ishida foydalanadi.", "note": null},
  {"num": 87, "time": "00:06:11,719 --> 00:06:15,219", "arabic": "كَمَا أَظُنُّهُ لَا يَرْجِعُ إِلَيْكَ فِي كَثِيرٍ مِنَ الْأُمُورِ", "segs": null, "full_uz": "Menimcha, u ko'p ishlarda siz bilan maslahatlashmaydi ham.", "note": null},
  {"num": 88, "time": "00:06:15,220 --> 00:06:20,120", "arabic": "لَسْتِ أَوَّلَ مَنْ يَقُولُ لِي ذَلِكَ يَا زُبَيْدَةُ", "segs": null, "full_uz": "Senga bu gapni aytgan birinchi kishi emassan, Zubayda.", "note": null},
  {"num": 89, "time": "00:06:20,120 --> 00:06:24,920", "arabic": "وَلَا أَدْرِي سَبَبَ كَرْهِكُمْ لِجَعْفَرٍ", "segs": null, "full_uz": "Va Ja'farni yomon ko'rishingizning sababini bilmayman.", "note": null},
  {"num": 90, "time": "00:06:24,920 --> 00:06:29,500", "arabic": "مَا الَّذِي فَعَلَهُ جَعْفَرٌ حَتَّى يَسْتَحِقَّ مِنْكُمْ كُلَّ هَذَا الْكَرْهِ؟", "segs": null, "full_uz": "Ja'far sizlarning bunchalik nafratingizga loyiq bo'lish uchun nima qilgan?", "note": null},
  {"num": 91, "time": "00:06:29,500 --> 00:06:32,400", "arabic": "أَنْتِ مِنْ جِهَةٍ وَابْنُ الرَّبِيعِ مِنْ جِهَةٍ أُخْرَى", "segs": null, "full_uz": "Sen bir tomondan, Ibn Rabi ikkinchi tomondan.", "note": null},
  {"num": 92, "time": "00:06:32,400 --> 00:06:33,600", "arabic": "مَا الَّذِي فَعَلَهُ جَعْفَرٌ", "segs": null, "full_uz": "Ja'far nima qilgan?", "note": null},
  {"num": 93, "time": "00:06:33,600 --> 00:06:35,760", "arabic": "إِذَا أَذِنْتَ لِي يَا مَوْلَايَ", "segs": null, "full_uz": "Agar menga ruxsat bersangiz, xo'jayinim.", "note": null},
  {"num": 94, "time": "00:06:35,760 --> 00:06:38,400", "arabic": "إِنَّمَا يَقُومُ بِهِ جَعْفَرٌ", "segs": null, "full_uz": "Ja'far qilayotgan narsa aynan shu.", "note": null},
  {"num": 95, "time": "00:06:38,400 --> 00:06:40,940", "arabic": "يُثِيرُ حَفِيظَةَ النَّاسِ عَلَيْهِ", "segs": null, "full_uz": "Odamlarning unga nisbatan g'azabini keltirib chiqarmoqda.", "note": null},
  {"num": 96, "time": "00:06:40,940 --> 00:06:44,540", "arabic": "وَمِنْهُمْ أَنْتَ؟", "segs": null, "full_uz": "Ulardan sen ham bormisan?", "note": null},
  {"num": 97, "time": "00:06:44,540 --> 00:06:50,000", "arabic": "أَنَا وَغَيْرِي، إِنَّ جَعْفَرًا يَتَصَرَّفُ بِأُمُورِ الْخِلَافَةِ كَمَا لَوْ كَانَ هُوَ", "segs": null, "full_uz": "Men ham, boshqalar ham. Ja'far xalifalik ishlarida xuddi o'zi bo'lgandek harakat qiladi.", "note": null},
  {"num": 98, "time": "00:06:50,000 --> 00:06:54,840", "arabic": "فَلْيَعْذِرْنِي مَوْلَايَ، كَمَا لَوْ كَانَ هُوَ أَمِيرَ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Xo'jayinim meni kechirsin, xuddi u mo'minlar amiri bo'lgandek.", "note": null},
  {"num": 99, "time": "00:06:54,840 --> 00:06:57,540", "arabic": "وَمَاذَا فِي ذَلِكَ يَا عِيسَى؟", "segs": null, "full_uz": "Bunda nima ayb bor, Iso?", "note": null},
  {"num": 100, "time": "00:06:59,560 --> 00:07:01,540", "arabic": "أَلَيْسَ هُوَ صَاحِبَ أَمِيرِ الْمُؤْمِنِينَ؟", "segs": null, "full_uz": "U mo'minlar amirining safdoshi emasmi?", "note": null},
  {"num": 101, "time": "00:07:03,120 --> 00:07:04,540", "arabic": "أَلَيْسَ هُوَ ابْنَ وَزِيرِهِ؟", "segs": null, "full_uz": "U vaziri o'g'li emasmi?", "note": null},
  {"num": 102, "time": "00:07:06,520 --> 00:07:08,540", "arabic": "أَلَيْسَ هُوَ ابْنَ أُمِّهِ فِي الرَّضَاعَةِ؟", "segs": null, "full_uz": "U emikdosh onasining o'g'li emasmi?", "note": "«أُمّ فِي الرَّضَاعَةِ» — emizikli ona, ya'ni bir sut emgan qarindoshlik ma'nosida."},
  {"num": 103, "time": "00:07:10,140 --> 00:07:13,740", "arabic": "أَلَيْسَ هُوَ كُفُؤًا لِأَيِّ مَهَمَّةٍ تُسْنَدُ إِلَيْهِ؟", "segs": null, "full_uz": "U o'ziga topshiriladigan har qanday vazifaga loyiq emasmi?", "note": null},
  {"num": 104, "time": "00:07:14,540 --> 00:07:19,340", "arabic": "كُلُّهُ لَا يَمْنَحُهُ الْحَقَّ فِي أَنْ يَتَصَرَّفَ كَمَا لَوْ كَانَ السَّيِّدَ الْأَوْحَدَ فِي الدَّوْلَةِ", "segs": null, "full_uz": "Bularning barchasi unga davlatda yagona hukmdordek harakat qilish huquqini bermaydi.", "note": null},
  {"num": 105, "time": "00:07:19,340 --> 00:07:25,040", "arabic": "هَارُونُ يَا مَوْلَايَ إِنَّ دَوْلَةً أُخْرَى تَتَوَلَّدُ دَاخِلَ دَوْلَتِكَ دَوْلَةَ الْبَرَامِكَ", "segs": null, "full_uz": "Horun, xo'jayinim, sizning davlatingiz ichida yana bir davlat — Baramaklar davlati tug'ilmoqda.", "note": null},
  {"num": 106, "time": "00:07:25,040 --> 00:07:32,259", "arabic": "يَا زُبَيْدَةُ وَاللَّهِ إِنَّكُمْ تُهَوِّلُونَ الْأَمْرَ كَثِيرًا إِنَّ دَوْلَةَ الْبَرَامِكَ كَمَا", "segs": null, "full_uz": "Ey Zubayda, Alloh haqqi, siz masalani juda ham kattalashtiryapsiz. Baramaklar davlati, sizlar...", "note": null},
  {"num": 107, "time": "00:07:32,259 --> 00:07:39,960", "arabic": "تُسَمُّونَهَا إِنَّمَا هِيَ تَحْتَ خِدْمَتِي وَتَحْتَ سُلْطَانِي وَاللَّهِ يَا عِيسَى إِنَّ النِّطْعَ", "segs": null, "full_uz": "deb ataysizlar, u mening xizmatimda va hukmronligim ostidadir. Alloh haqqi, Iso...", "note": null},
  {"num": 108, "time": "00:07:39,959 --> 00:07:44,779", "arabic": "وَالسَّيْفُ جَاهِزَانِ لِكُلِّ مَنْ تُسَوِّلُ لَهُ نَفْسُهُ الْعَبَثَ بِأَمْنِ هَذِهِ الدَّوْلَةِ", "segs": null, "full_uz": "Jazo gilami va qilich — bu davlat xavfsizligi bilan o'ynashni ko'ngliga keltirgan har bir kishi uchun tayyor.", "note": null},
  {"num": 109, "time": "00:07:44,779 --> 00:07:47,159", "arabic": "حَتَّى وَلَوْ كَانَ مِنْ بَنِي الْعَبَّاسِ أَنْفُسِهِمْ", "segs": null, "full_uz": "Hatto Abbosiylarning o'zlaridan bo'lsa ham.", "note": null},
  {"num": 110, "time": "00:07:47,159 --> 00:07:51,939", "arabic": "قُلْتُ لِلسَّيِّدِ صُهَيْبٍ إِنَّ قَوْلِي لِابْنِ حَنْبَلٍ بِأَنِّي سَأَتْرُكُ الدُّكَّانَ", "segs": null, "full_uz": "Janob Suhaybga aytdimki, Ibn Hanbalga do'konni tark etaman deb aytishim...", "note": null},
  {"num": 111, "time": "00:07:51,939 --> 00:07:54,740", "arabic": "رُبَّمَا قَطَعَ رِزْقِي وَرِزْقَ أَهْلِي وَأَوْلَادِي", "segs": null, "full_uz": "balki mening va oilam, bolalarimning rizqini kesib qo'yishi mumkin.", "note": null},
  {"num": 112, "time": "00:07:54,740 --> 00:07:58,339", "arabic": "قُلْنَا لَكَ يَا عَامِرُ مُجَرَّدُ قَوْلٍ لَا أَكْثَرَ", "segs": null, "full_uz": "Senga aytdik-ku, Omir, shunchaki gap, xolos.", "note": null},
  {"num": 113, "time": "00:07:58,339 --> 00:08:02,179", "arabic": "وَلَكِنْ يَا سَلَمَةُ أَيُنَفَّذُ وَحْدَهُ أَمْ لَا؟", "segs": null, "full_uz": "Lekin, Salama, bu yolg'iz o'zi amalga oshadimi yoki yo'q?", "note": null},
  {"num": 114, "time": "00:08:02,179 --> 00:08:06,759", "arabic": "يَبْدُو حَلًّا مُنَاسِبًا فَبِهَذِهِ الطَّرِيقَةِ يُضْطَرُّ ابْنُ حَنْبَلٍ لِبَيْعِ الدُّكَّانِ", "segs": null, "full_uz": "Bu maqbul yechim ko'rinadi, shu yo'l bilan Ibn Hanbal do'konni sotishga majbur bo'ladi.", "note": null},
  {"num": 115, "time": "00:08:06,759 --> 00:08:08,779", "arabic": "وَتَظْفَرُ أَنْتَ بِالْمِئَةِ دِرْهَمٍ", "segs": null, "full_uz": "Va sen yuz dirhamga erishasan.", "note": null},
  {"num": 116, "time": "00:08:08,779 --> 00:08:14,179", "arabic": "مِئَةُ دِرْهَمٍ سَأُحَاوِلُ يَا سَلَمَةُ فَالْمِئَةُ دِرْهَمٍ تَسْتَحِقُّ الْمُحَاوَلَةَ", "segs": null, "full_uz": "Yuz dirham... urinib ko'raman, Salama, yuz dirham urinishga arziydi.", "note": null},
  {"num": 117, "time": "00:08:14,179 --> 00:08:20,859", "arabic": "مَهْمَا يَكُنْ صَحِيحٌ هَلْ أَكَّدَ لَكَ صُهَيْبٌ هَذَا أَنَّهُ سَيَتْرُكُكَ تَعْمَلُ فِي هَذَا الدُّكَّانِ؟", "segs": null, "full_uz": "Nima bo'lishidan qat'i nazar — bu Suhayb senga shu do'konda ishlashingga qo'yishini aniq tasdiqladimi?", "note": null},
  {"num": 118, "time": "00:08:20,859 --> 00:08:23,359", "arabic": "فِيمَا لَوْ نَجَحْتَ فِي إِقْنَاعِ أَحْمَدَ بِبَيْعِهَا", "segs": null, "full_uz": "Agar Ahmadni uni sotishga ko'ndira olsang.", "note": null},
  {"num": 119, "time": "00:08:23,359 --> 00:08:29,699", "arabic": "أَجَلْ أَجَلْ يَا سَلَمَةُ وَلَكِنْ لَا أَكْتُمُكَ سِرًّا أَنَا مُتَخَوِّفٌ مِنْ غَضَبِ أَحْمَدَ", "segs": null, "full_uz": "Ha, ha, Salama, lekin sendan sirni yashirmayman — Ahmadning g'azabidan qo'rqaman.", "note": null},
  {"num": 120, "time": "00:08:29,699 --> 00:08:32,419", "arabic": "فَهُوَ مُصَمِّمٌ عَلَى عَدَمِ بَيْعِ دُكَّانِهِ", "segs": null, "full_uz": "U do'konini sotmaslikka qat'iy qaror qilgan.", "note": null},
  {"num": 121, "time": "00:08:32,419 --> 00:08:37,079", "arabic": "مَاذَا لَوْ قَالَ لِي إِنْ كُنْتَ تُرِيدُ يَا عَامِرُ تَرْكَ الدُّكَّانِ فَاتْرُكْهَا", "segs": null, "full_uz": "Agar u menga: «Agar do'konni tark etishni xohlasang, Omir, tark et», desa-chi?", "note": null},
  {"num": 122, "time": "00:08:37,080 --> 00:08:40,200", "arabic": "عِنْدَهَا سَأَكُونُ قَدْ خَسِرْتُ مَرَّتَيْنِ", "segs": null, "full_uz": "Shunda men ikki marta yutqazgan bo'laman.", "note": null},
  {"num": 123, "time": "00:08:40,200 --> 00:08:42,540", "arabic": "لَا لَا أَظُنُّهُ سَيَفْعَلُ ذَلِكَ", "segs": null, "full_uz": "Yo'q, u buni qiladi deb o'ylamayman.", "note": null},
  {"num": 124, "time": "00:08:42,540 --> 00:08:45,259", "arabic": "لَيْسَ لَدَيْهِ إِلَّا الدُّكَّانَ مَوْرِدًا لِرِزْقِهِ", "segs": null, "full_uz": "Uning rizq manbai faqat shu do'kon.", "note": null},
  {"num": 125, "time": "00:08:45,259 --> 00:08:48,860", "arabic": "ثُمَّ مِنْ أَيْنَ سَيَجِدُ مُسْتَأْجِرًا آخَرَ لِدُكَّانِهِ؟", "segs": null, "full_uz": "So'ngra do'koniga boshqa ijarachini qayerdan topadi?", "note": null},
  {"num": 126, "time": "00:08:48,860 --> 00:08:52,480", "arabic": "إِنَّمَا عَرْضُهُ عَلَيْكَ صُهَيْبٌ هَذَا لَيْسَ ذَا جَدْوَى", "segs": null, "full_uz": "Suhaybning senga taklifi foydasiz.", "note": null},
  {"num": 127, "time": "00:08:52,480 --> 00:08:55,460", "arabic": "فَلَا تُضَيِّعْ وَقْتَكَ مَعَهُ وَالْتَفِتْ إِلَى مَا يَنْفَعُكَ", "segs": null, "full_uz": "Vaqtingni u bilan behuda sarflama, senga foyda beradigan narsaga e'tibor qarat.", "note": null},
  {"num": 128, "time": "00:08:55,460 --> 00:08:58,420", "arabic": "كَيْفَ يَا أُمِّي؟", "segs": null, "full_uz": "Qanday, onajon?", "note": null},
  {"num": 129, "time": "00:08:58,420 --> 00:09:00,840", "arabic": "إِنَّهُ يَضَعُكَ فِي وَجْهِ الْعَاصِفَةِ وَحْدَكَ", "segs": null, "full_uz": "U seni yolg'iz o'zingni bo'ronning oldiga qo'yyapti.", "note": null},
  {"num": 130, "time": "00:09:00,840 --> 00:09:04,120", "arabic": "فَإِنْ هَدَأَتْ لَنْ تَجِدَ نَفْسَكَ إِلَّا عَارِيًا", "segs": null, "full_uz": "Bo'ron tinganda, o'zingni yalang'och holda topasan, xolos.", "note": null},
  {"num": 131, "time": "00:09:04,120 --> 00:09:10,120", "arabic": "عَاصِفَةٌ؟ عَاصِفَةٌ؟", "segs": null, "full_uz": "Bo'ronmi? Bo'ronmi?", "note": null},
  {"num": 132, "time": "00:09:10,120 --> 00:09:13,399", "arabic": "أَيُّ عَاصِفَةٍ تِلْكَ يَا أُمِّي؟", "segs": null, "full_uz": "Bu qanday bo'ron, onajon?", "note": null},
  {"num": 133, "time": "00:09:13,399 --> 00:09:16,200", "arabic": "أَقْصِدُ أَنَّكَ لَوْ فَشِلْتَ فِي الضَّغْطِ عَلَى ابْنِ حَنْبَلٍ", "segs": null, "full_uz": "Demoqchimanki, agar Ibn Hanbalga bosim o'tkazishda muvaffaqiyatsizlikka uchrasang.", "note": null},
  {"num": 134, "time": "00:09:16,200 --> 00:09:17,980", "arabic": "وَأَظُنُّكَ سَتَفْشَلُ", "segs": null, "full_uz": "Va menimcha, sen muvaffaqiyatsizlikka uchraysan.", "note": null},
  {"num": 135, "time": "00:09:17,980 --> 00:09:21,860", "arabic": "فَسَتَكُونُ الْعَوَاقِبُ الْوَخِيمَةُ عَلَى رَأْسِكَ وَحْدَكَ", "segs": null, "full_uz": "Og'ir oqibatlar faqat sening o'z boshingga tushadi.", "note": null},
  {"num": 136, "time": "00:09:21,860 --> 00:09:24,820", "arabic": "وَإِنْ طَرَدَكَ ابْنُ حَنْبَلٍ مِنَ الدُّكَّانِ", "segs": null, "full_uz": "Va agar Ibn Hanbal seni do'kondan haydab yuborsa.", "note": null},
  {"num": 137, "time": "00:09:24,820 --> 00:09:28,200", "arabic": "أَيْنَ سَتَذْهَبُ؟", "segs": null, "full_uz": "Qayerga borasan?", "note": null},
  {"num": 138, "time": "00:09:28,200 --> 00:09:31,279", "arabic": "اَلْحَقِيقَةُ يَا أُمِّي لَمْ أُفَكِّرْ", "segs": null, "full_uz": "Rostini aytsam, onajon, o'ylamagan edim.", "note": null},
  {"num": 139, "time": "00:09:31,279 --> 00:09:40,600", "arabic": "إِذَنْ فَالْفِكْرَةُ الَّتِي عَرَضَهَا عَلَيْكَ صُهَيْبٌ هَذَا لَنْ تَضُرَّ إِلَّا وَاحِدًا هُوَ أَنْتَ أَيُّهَا الْأَحْمَقُ", "segs": [{"ar": "إِذَنْ فَالْفِكْرَةُ الَّتِي عَرَضَهَا عَلَيْكَ صُهَيْبٌ هَذَا", "uz": "demak, Suhayb senga taklif qilgan g'oya"}, {"ar": "لَنْ تَضُرَّ إِلَّا وَاحِدًا هُوَ أَنْتَ أَيُّهَا الْأَحْمَقُ", "uz": "faqat bitta odamga — senga, ey ahmoq — zarar keltiradi"}], "full_uz": "Demak, Suhayb senga taklif qilgan g'oya faqat bitta odamga — senga, ey ahmoq — zarar keltiradi.", "note": null},
  {"num": 140, "time": "00:09:40,600 --> 00:09:45,139", "arabic": "تَضُرُّ؟ مَا الْحَلُّ يَا أُمِّي؟ مَا الْحَلُّ يَا سَلَمَةُ؟", "segs": null, "full_uz": "Zarar keladimi? Yechim nima, onajon? Yechim nima, Salama?", "note": null},
  {"num": 141, "time": "00:09:45,139 --> 00:09:50,100", "arabic": "اَلْحَلُّ الْمُنَاسِبُ أَنْ تَتْرُكَ هَذَا الْأَمْرَ بِرُمَّتِهِ وَلَا تُجَازِفَ بِعَمَلِكَ وَرِزْقِكَ", "segs": [{"ar": "اَلْحَلُّ الْمُنَاسِبُ أَنْ تَتْرُكَ هَذَا الْأَمْرَ بِرُمَّتِهِ", "uz": "eng maqbul yechim — bu ishni butunlay tashlash"}, {"ar": "وَلَا تُجَازِفَ بِعَمَلِكَ وَرِزْقِكَ", "uz": "ish va rizqingni xavf ostiga qo'ymaslik"}], "full_uz": "Eng maqbul yechim — bu ishni butunlay tashlab, ish va rizqingni xavf ostiga qo'ymaslikdir.", "note": null},
  {"num": 142, "time": "00:09:50,100 --> 00:09:52,279", "arabic": "وَأَتْرُكُ مِئَةً مِنَ الدَّرَاهِمِ؟", "segs": null, "full_uz": "Va yuz dirhamdan voz kechaymi?", "note": null},
  {"num": 143, "time": "00:09:52,980 --> 00:09:54,279", "arabic": "لَدَيَّ رَأْيٌ آخَرُ", "segs": null, "full_uz": "Mening boshqa fikrim bor.", "note": null},
  {"num": 144, "time": "00:09:54,279 --> 00:09:57,079", "arabic": "أَخْبِرِينِي بِهِ يَا أُمَّ عَامِرٍ", "segs": null, "full_uz": "Ayt-chi buni menga, Umm Omir.", "note": null},
  {"num": 146, "time": "00:10:30,279 --> 00:10:40,939", "arabic": "حَمْدًا مَا بِكِ؟", "segs": null, "full_uz": "Hamda, senga nima bo'ldi?", "note": null},
  {"num": 147, "time": "00:10:40,939 --> 00:10:44,539", "arabic": "إِنَّمَا اشْتَقْتُ لِمُحَمَّدٍ يَا أُمِّي", "segs": null, "full_uz": "Men shunchaki Muhammadni sog'indim, onajon.", "note": null},
  {"num": 148, "time": "00:10:44,539 --> 00:10:48,799", "arabic": "لَمْ نَسْمَعْ عَنْهُ خَبَرًا مُنْذُ خُرُوجِهِ إِلَى الْيَمَنِ", "segs": null, "full_uz": "Yamanga ketganidan beri undan hech qanday xabar eshitmadik.", "note": null},
  {"num": 149, "time": "00:10:48,799 --> 00:10:55,600", "arabic": "زَوْجُكِ يَا ابْنَتِي لَا يُلْقِي عَصًا مُنْذُ أَنْ كَانَ صَغِيرًا", "segs": null, "full_uz": "Eringiz, qizim, kichikligidan beri bir joyda tinch o'tirmagan.", "note": "«لَا يُلْقِي عَصًا» — bir joyda qaror topmaslik, doim safarda bo'lish ma'nosidagi ibora."},
  {"num": 150, "time": "00:10:55,600 --> 00:10:58,439", "arabic": "يُحِبُّ التَّنَقُّلَ وَالسَّفَرَ", "segs": null, "full_uz": "Sayohat va ko'chib yurishni yaxshi ko'radi.", "note": null},
  {"num": 151, "time": "00:10:58,440 --> 00:11:04,680", "arabic": "مَاذَا أَقُولُ أَنَا إِذَنْ؟ أَنَا الَّتِي لَمْ أَهْنَأْ بِجَانِبِهِ يَوْمًا كَامِلًا", "segs": null, "full_uz": "Unda men nima deyman? Men uning yonida to'liq bir kun ham rohatlanmaganman.", "note": null},
  {"num": 152, "time": "00:11:04,680 --> 00:11:09,120", "arabic": "لَا أَدْرِي مَا أَقُولُ لَكِ يَا عَمَّتِي", "segs": null, "full_uz": "Senga nima deyishni bilmayapman, ammajon.", "note": null},
  {"num": 153, "time": "00:11:09,120 --> 00:11:13,060", "arabic": "إِنَّنِي أَخْشَى أَنْ مَكْرُوهًا أَلَمَّ بِهِ", "segs": null, "full_uz": "Unga yomon narsa yuz berganidan qo'rqyapman.", "note": null},
  {"num": 154, "time": "00:11:13,060 --> 00:11:21,680", "arabic": "يَا عَمَّتِي يَضِيقُ صَدْرِي وَلَا يَنْطَلِقُ لِسَانِي فَرَقًا عَلَى مُحَمَّدٍ", "segs": null, "full_uz": "Ammajon, Muhammad uchun qo'rquvdan ko'nglim siqiladi va tilim aylanmaydi.", "note": null},
  {"num": 155, "time": "00:11:21,680 --> 00:11:25,900", "arabic": "وَقَلْبِي يُحَدِّثُنِي أَنَّ مُحَمَّدًا فِي ضِيقٍ", "segs": null, "full_uz": "Va yuragim menga Muhammad qiynalgan ekan, deb aytyapti.", "note": null},
  {"num": 156, "time": "00:11:25,899 --> 00:11:31,340", "arabic": "اِسْتَغْفِرِ اللَّهَ يَا ابْنَتِي اِسْتَغْفِرِ اللَّهَ وَاسْتَعِيذِي بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ", "segs": null, "full_uz": "Alloh'dan mag'firat so'ra, qizim, Alloh'dan mag'firat so'ra va la'natlangan shaytondan Allohga sig'in.", "note": null},
  {"num": 157, "time": "00:11:31,340 --> 00:11:36,500", "arabic": "قُومِي يَا ابْنَتِي قُومِي تَوَضَّئِي وَصَلِّي رَكْعَتَيْنِ", "segs": null, "full_uz": "Tur, qizim, tur, tahorat qil va ikki rakat namoz o'qi.", "note": null},
  {"num": 158, "time": "00:11:36,500 --> 00:11:42,159", "arabic": "وَاسْأَلِي اللَّهَ أَنْ يَحْفَظَ مُحَمَّدًا إِنَّهُ خَيْرُ الْحَافِظِينَ", "segs": null, "full_uz": "Va Allohdan Muhammadni asrashini so'ra, U eng yaxshi Asrovchidir.", "note": null},
  {"num": 159, "time": "00:11:42,159 --> 00:11:44,659", "arabic": "أَفْعَلُ إِنْ شَاءَ اللَّهُ", "segs": null, "full_uz": "Alloh xohlasa, shunday qilaman.", "note": null},
  {"num": 160, "time": "00:11:44,659 --> 00:11:51,600", "arabic": "بَارَكَ اللَّهُ فِيكِ ابْنَتِي بَارَكَ اللَّهُ فِيكِ", "segs": null, "full_uz": "Alloh senga barakot bersin, qizim, Alloh senga barakot bersin.", "note": null},
  {"num": 161, "time": "00:11:51,600 --> 00:11:54,840", "arabic": "تَعَالَيْ تَعَالَيْ يَا ابْنَتِي", "segs": null, "full_uz": "Kel, kel, qizginam.", "note": null},
  {"num": 162, "time": "00:11:54,840 --> 00:11:59,500", "arabic": "تَفَضَّلْ", "segs": null, "full_uz": "Marhamat.", "note": null},
  {"num": 164, "time": "00:12:02,540 --> 00:12:04,320", "arabic": "اِسْتَرِحْ", "segs": null, "full_uz": "Dam ol.", "note": null},
  {"num": 165, "time": "00:12:04,320 --> 00:12:10,080", "arabic": "بَارَكَ اللَّهُ فِيكَ", "segs": null, "full_uz": "Alloh senga barakot bersin.", "note": null},
  {"num": 166, "time": "00:12:10,080 --> 00:12:12,460", "arabic": "أَتَدْرِي أَيُّهَا الشَّافِعِيُّ", "segs": null, "full_uz": "Bilasanmi, ey Shofi'iy.", "note": null},
  {"num": 167, "time": "00:12:12,460 --> 00:12:14,560", "arabic": "مُنْذُ أَنْ عَرَفْتُكَ", "segs": null, "full_uz": "Seni tanigandan beri.", "note": null},
  {"num": 168, "time": "00:12:14,560 --> 00:12:17,200", "arabic": "أَخَذَتْنِي الْحَيْرَةُ فِي شَأْنِكَ", "segs": null, "full_uz": "Sen haqingda hayronlik meni chulg'ab oldi.", "note": null},
  {"num": 169, "time": "00:12:17,200 --> 00:12:21,160", "arabic": "وَمَا سَبَبُ تِلْكَ الْحَيْرَةِ؟", "segs": null, "full_uz": "Bu hayronlikning sababi nima?", "note": null},
  {"num": 170, "time": "00:12:21,160 --> 00:12:23,240", "arabic": "كُلُّ الَّذِينَ عَرَفْتُهُمْ فِي هَذَا السِّجْنِ", "segs": null, "full_uz": "Bu zindonda tanigan hammam.", "note": null},
  {"num": 171, "time": "00:12:23,240 --> 00:12:26,200", "arabic": "كَانُوا لَا يَعْرِفُونَ لِلنَّوْمِ طَرِيقًا", "segs": null, "full_uz": "Ular uxlashning yo'lini bilishmasdi.", "note": null},
  {"num": 172, "time": "00:12:26,200 --> 00:12:28,080", "arabic": "أَمَّا أَنْتَ", "segs": null, "full_uz": "Sen esa.", "note": null},
  {"num": 173, "time": "00:12:28,080 --> 00:12:31,019", "arabic": "فَمَا فَارَقَتْكَ الطُّمَأْنِينَةُ", "segs": null, "full_uz": "Xotirjamlik sendan hech qachon ayrilmagan.", "note": null},
  {"num": 174, "time": "00:12:31,019 --> 00:12:36,980", "arabic": "أَنْ آمَنَ بِقَضَاءِ اللَّهِ وَقَدَرِهِ", "segs": null, "full_uz": "Allohning qazo va qadariga ishonganim uchun.", "note": null},
  {"num": 175, "time": "00:12:36,980 --> 00:12:38,519", "arabic": "كَفَى", "segs": null, "full_uz": "Yetarli.", "note": null},
  {"num": 176, "time": "00:12:38,519 --> 00:12:43,620", "arabic": "وَمَا نَفَرَ مِنْ قَدَرٍ إِلَّا إِلَى قَدَرٍ", "segs": null, "full_uz": "Taqdirdan qochgan kishi faqat boshqa bir taqdirga yo'liqadi.", "note": "Taqdirdan qochib bo'lmasligi haqidagi hikmatli ibora."},
  {"num": 177, "time": "00:12:43,620 --> 00:12:45,240", "arabic": "صَدَقْتَ يَا شَافِعِيُّ", "segs": null, "full_uz": "Haq gap aytding, ey Shofi'iy.", "note": null},
  {"num": 178, "time": "00:12:45,240 --> 00:12:46,259", "arabic": "وَلَكِنْ", "segs": null, "full_uz": "Lekin.", "note": null},
  {"num": 179, "time": "00:12:46,259 --> 00:12:49,159", "arabic": "أَتَظُنُّ أَنَّ أَمِيرَ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Mo'minlar amiri deb o'ylaysanmi...", "note": null},
  {"num": 180, "time": "00:12:49,159 --> 00:12:50,940", "arabic": "قَدْ أَقْنَعَهُ كَلَامُكَ", "segs": null, "full_uz": "...gaping uni ko'ndirgan bo'lsa?", "note": null},
  {"num": 181, "time": "00:12:50,940 --> 00:12:57,940", "arabic": "وَيُنَجِّي اللَّهُ الَّذِينَ اتَّقَوْا بِمَفَازَتِهِمْ لَا يَمَسُّهُمُ السُّوءُ", "segs": null, "full_uz": "Alloh taqvodorlarni najotlari bilan qutqaradi, ularga yomonlik tegmaydi.", "note": "Qur'ondagi (Zumar, 61-oyat) iqtibos."},
  {"num": 182, "time": "00:12:57,940 --> 00:13:01,840", "arabic": "وَاللَّهِ مَا قُلْتُ كَلِمَةً إِلَّا صَادِقًا", "segs": null, "full_uz": "Alloh haqqi, men aytgan har bir so'zim rost edi.", "note": null},
  {"num": 183, "time": "00:13:01,840 --> 00:13:06,840", "arabic": "وَمَا ظَنَنْتُ أَمِيرَ الْمُؤْمِنِينَ يُنْزِلُ الْعِقَابَ بِمَظْلُومٍ", "segs": null, "full_uz": "Va mo'minlar amiri mazlumga jazo beradi, deb o'ylamagandim.", "note": null},
  {"num": 184, "time": "00:13:06,840 --> 00:13:18,820", "arabic": "مَوْلَايَ أَمِيرُ الْمُؤْمِنِينَ لَا يَظْلِمُ أَحَدًا", "segs": null, "full_uz": "Xo'jayinim, mo'minlar amiri hech kimga zulm qilmaydi.", "note": null},
  {"num": 185, "time": "00:13:18,820 --> 00:13:25,400", "arabic": "وَلَكِنْ مَنْ وَرَاءَهُ فَهُمْ مَنْبَعُ الْقَلَقِ وَمَوْطِنُ الْخَوْفِ", "segs": null, "full_uz": "Lekin uning ortidagilar — ular tashvish manbai va qo'rquv makonidir.", "note": null},
  {"num": 186, "time": "00:13:25,400 --> 00:13:32,020", "arabic": "فَالْأَدِلَّةُ تُحَاكُ وَالتُّهَمُ تُلَفَّقُ", "segs": null, "full_uz": "Dalillar to'qiladi, ayblovlar uydiriladi.", "note": null},
  {"num": 187, "time": "00:13:32,020 --> 00:13:37,740", "arabic": "وَبَعْدَهَا تُزْهَقُ الْأَرْوَاحُ وَتُقْطَعُ الرُّؤُوسُ", "segs": null, "full_uz": "So'ngra jonlar olinadi va boshlar kesiladi.", "note": null},
  {"num": 188, "time": "00:13:41,040 --> 00:13:43,880", "arabic": "أَمَّا أَنَا فَقَدْ فَوَّضْتُ أَمْرِي إِلَى اللَّهِ", "segs": null, "full_uz": "Men esa ishimni Allohga topshirdim.", "note": null},
  {"num": 189, "time": "00:13:43,880 --> 00:13:48,680", "arabic": "قُلْ لَنْ يُصِيبَنَا إِلَّا مَا كَتَبَ اللَّهُ لَنَا", "segs": null, "full_uz": "Ayt: bizga faqat Alloh yozgan narsa yetadi.", "note": "Qur'ondagi (Tavba, 51-oyat) ma'nosiga ishora."},
  {"num": 190, "time": "00:13:48,679 --> 00:13:52,059", "arabic": "قَلِيلٌ مَنْ يَدْخُلُ هَذَا الْمَكَانَ وَيَتَعَلَّقُ بِهِ قَلْبِي", "segs": null, "full_uz": "Bu joyga kirib, qalbim bog'lanadigan kishilar kam.", "note": null},
  {"num": 191, "time": "00:13:52,059 --> 00:13:55,120", "arabic": "فَكَمْ مَلَكْتَ عَلَيَّ نَفْسِي أَيُّهَا الرَّجُلُ", "segs": null, "full_uz": "Sen qanchalar mening qalbimni egallab olding, ey kishi.", "note": null},
  {"num": 192, "time": "00:13:55,120 --> 00:13:59,779", "arabic": "وَكَمْ أَرْجُو أَنْ يُظْهِرَ اللَّهُ بَرَاءَتَكَ أَيُّهَا الشَّافِعِيُّ", "segs": null, "full_uz": "Va qanchalar Alloh sening pokligingni namoyon qilishini istayman, ey Shofi'iy.", "note": null},
  {"num": 193, "time": "00:14:18,679 --> 00:14:34,979", "arabic": "قُلْ لِي يَا أَخِي", "segs": null, "full_uz": "Ayt-chi, akajon.", "note": null},
  {"num": 194, "time": "00:14:34,979 --> 00:14:39,139", "arabic": "كَيْفَ رَأَيْتَ أَمِيرَ الْمُؤْمِنِينَ الْيَوْمَ؟", "segs": null, "full_uz": "Bugun mo'minlar amirini qanday ko'rding?", "note": null},
  {"num": 195, "time": "00:14:42,139 --> 00:14:43,779", "arabic": "اِسْمَعْ أَيُّهَا الرَّجُلُ", "segs": null, "full_uz": "Eshit, ey kishi.", "note": null},
  {"num": 196, "time": "00:14:43,779 --> 00:14:48,199", "arabic": "لَا أَعْرِفُ لِمَ ارْتَاحَتْ نَفْسِي لَكَ", "segs": null, "full_uz": "Bilmayman, nega qalbim senga ishondi.", "note": null},
  {"num": 197, "time": "00:14:48,200 --> 00:14:51,320", "arabic": "وَلَكِنِّي لَنْ أُزَخْرِفَ لَكَ الْقَوْلَ", "segs": null, "full_uz": "Lekin senga gapni bezab aytmayman.", "note": null},
  {"num": 198, "time": "00:14:51,320 --> 00:14:55,420", "arabic": "إِنَّ الْأُمُورَ تَمْضِي عَلَى غَيْرِ مَا تُحِبُّ", "segs": null, "full_uz": "Ishlar sen istagandek ketmayapti.", "note": null},
  {"num": 199, "time": "00:14:55,420 --> 00:14:58,740", "arabic": "قَدْ جِئْتُكَ مِنْ عِنْدِ أَمِيرِ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Mo'minlar amiri huzuridan senga keldim.", "note": null},
  {"num": 200, "time": "00:14:58,740 --> 00:15:01,620", "arabic": "وَهُوَ عَلَى مَا يَبْدُو مُتَكَدِّرُ الْمِزَاجِ", "segs": null, "full_uz": "U ko'rinishidan noxush kayfiyatda.", "note": null},
  {"num": 201, "time": "00:15:01,620 --> 00:15:06,740", "arabic": "وَقَدْ طَلَبَ رُؤْيَتَكَ مِنْ دُونِ الْآخَرِينَ", "segs": null, "full_uz": "Va boshqalardan alohida seni ko'rishni so'radi.", "note": null},
  {"num": 202, "time": "00:15:06,740 --> 00:15:12,520", "arabic": "وَلَرُبَّ نَازِلَةٍ يَضِيقُ بِهَا الْفَتَى ذَرْعًا", "segs": null, "full_uz": "Ba'zan bir musibat yigitni chorasiz qoldiradi.", "note": null},
  {"num": 203, "time": "00:15:12,520 --> 00:15:15,620", "arabic": "وَعِنْدَ اللَّهِ مِنْهَا الْمَخْرَجُ", "segs": null, "full_uz": "Ammo undan chiqish yo'li Alloh huzuridadir.", "note": null},
  {"num": 204, "time": "00:15:15,620 --> 00:15:17,640", "arabic": "ضَاقَتْ", "segs": null, "full_uz": "Tor bo'lib qoldi.", "note": null},
  {"num": 205, "time": "00:15:17,639 --> 00:15:22,319", "arabic": "فَلَمَّا اسْتَحْكَمَتْ حَلَقَاتُهَا فَرَجَتْ", "segs": null, "full_uz": "Halqalari tobora mahkamlanganda, u yorishib ketdi.", "note": null},
  {"num": 206, "time": "00:15:22,319 --> 00:15:24,439", "arabic": "وَكُنْتُ أَظُنُّهَا لَا تَفْرَجُ", "segs": null, "full_uz": "Men esa uning hech qachon yorishmaydi, deb o'ylagandim.", "note": null},
  {"num": 207, "time": "00:15:24,439 --> 00:15:30,360", "arabic": "فَلْنَمْضِ", "segs": null, "full_uz": "Yuraylik.", "note": null},
  {"num": 208, "time": "00:15:44,360 --> 00:15:46,779", "arabic": "اَلسُّجَنَاءُ فِي الْبَابِ يَا أَمِيرَ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Mahbuslar eshikda, ey mo'minlar amiri.", "note": null},
  {"num": 209, "time": "00:15:46,779 --> 00:15:50,339", "arabic": "اَلسُّجَنَاءُ مَعَ الشَّافِعِيِّ", "segs": null, "full_uz": "Mahbuslar Shofi'iy bilan birga.", "note": null},
  {"num": 211, "time": "00:15:53,220 --> 00:15:55,959", "arabic": "وَأَدْخِلِ الشَّافِعِيَّ فَقَطْ", "segs": null, "full_uz": "Faqat Shofi'iyni ichkariga kirit.", "note": null},
  {"num": 212, "time": "00:15:55,959 --> 00:15:57,899", "arabic": "أَمْرُكَ يَا مَوْلَايَ", "segs": null, "full_uz": "Xo'p bo'ladi, xo'jayinim.", "note": null},
  {"num": 213, "time": "00:16:16,779 --> 00:16:27,220", "arabic": "اَلسَّلَامُ عَلَى مَوْلَايَ أَمِيرِ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Xo'jayinim, mo'minlar amiriga salom bo'lsin.", "note": null},
  {"num": 214, "time": "00:16:27,220 --> 00:16:30,500", "arabic": "وَعَلَيْكَ السَّلَامُ يَا شَافِعِيُّ", "segs": null, "full_uz": "Senga ham salom bo'lsin, Shofi'iy.", "note": null},
  {"num": 215, "time": "00:16:30,500 --> 00:16:33,579", "arabic": "فَتَفَضَّلْ بِالْجُلُوسِ", "segs": null, "full_uz": "Marhamat, o'tiring.", "note": null},
  {"num": 216, "time": "00:16:41,480 --> 00:16:46,079", "arabic": "أَحْسَبُ يَا شَافِعِيُّ أَنَّ كَلَامَكَ بِالْأَمْسِ كَانَ صَادِقًا", "segs": null, "full_uz": "Menimcha, Shofi'iy, kechagi gaping rost edi.", "note": null},
  {"num": 217, "time": "00:16:46,080 --> 00:16:50,620", "arabic": "فَوَاللَّهِ لَقَدْ لَامَسَ قَلْبِي وَاطْمَأَنَّتْ إِلَيْهِ نَفْسِي", "segs": null, "full_uz": "Alloh haqqi, u yuragimga tegib, qalbim unga xotirjam bo'ldi.", "note": null},
  {"num": 218, "time": "00:16:50,620 --> 00:16:54,560", "arabic": "حَفِظَ اللَّهُ أَمِيرَ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Alloh mo'minlar amirini asrasin.", "note": null},
  {"num": 219, "time": "00:16:54,560 --> 00:16:58,100", "arabic": "وَحَفِظَ بِهِ دِينَهُ وَرَعِيَّتَهُ", "segs": null, "full_uz": "Va u orqali dinini va fuqarolarini asrasin.", "note": null},
  {"num": 220, "time": "00:16:58,100 --> 00:17:00,540", "arabic": "وَإِنَّنِي أُشْهِدُ اللَّهَ", "segs": null, "full_uz": "Va men Allohni guvoh qilaman.", "note": null},
  {"num": 221, "time": "00:17:00,540 --> 00:17:07,039", "arabic": "أَنَّنِي لَا أَحْمِلُ لِوَلِيِّ أَمْرِ الْمُؤْمِنِينَ هَارُونَ الرَّشِيدِ أَيَّ ضَغِينَةٍ", "segs": null, "full_uz": "Mo'minlarning hukmdori Horun ar-Rashidga hech qanday kina saqlamasligim haqida.", "note": null},
  {"num": 222, "time": "00:17:07,039 --> 00:17:13,740", "arabic": "وَلَا يَنْطَوِي ضَمِيرِي إِلَّا عَلَى الْوَلَاءِ وَالطَّاعَةِ وَالْإِذْعَانِ لِأَوَامِرِهِ", "segs": null, "full_uz": "Vijdonimda faqat sadoqat, itoat va uning buyruqlariga bo'ysunish bor.", "note": null},
  {"num": 223, "time": "00:17:13,740 --> 00:17:20,059", "arabic": "وَمَا دَارَ فِي خُلُدِي يَوْمًا أَنْ أُوعِزَ إِلَى مُسْلِمٍ بِالْخُرُوجِ عَلَى طَاعَتِكَ", "segs": null, "full_uz": "Hech qachon xayolimga biror musulmonni sizga itoatdan chiqishga undash kelmagan.", "note": null},
  {"num": 224, "time": "00:17:20,059 --> 00:17:24,380", "arabic": "لَا وَلَا حَدَّثْتُ بِهَا حَتَّى خَبِيئَةَ نَفْسِي", "segs": null, "full_uz": "Yo'q, hatto o'zimning ichki dunyomga ham bunday narsani aytmaganman.", "note": null},
  {"num": 225, "time": "00:17:24,380 --> 00:17:27,599", "arabic": "لَكِنْ يَا مَوْلَايَ", "segs": null, "full_uz": "Lekin, xo'jayinim.", "note": null},
  {"num": 226, "time": "00:17:27,599 --> 00:17:33,079", "arabic": "غَفَرَ اللَّهُ لِمَنْ خَافَ عَلَى لُعَاعَةٍ مِنَ الدُّنْيَا", "segs": null, "full_uz": "Alloh dunyoning arzimas bir bo'lagidan qo'rqqan kishini mag'firat qilsin.", "note": "«لُعَاعَة» — arzimas, kichik narsa ma'nosida."},
  {"num": 227, "time": "00:17:33,079 --> 00:17:38,059", "arabic": "فَأَنْسَتْهُ الْخَوْفَ مِنَ اللَّهِ وَالدَّارِ الْآخِرَةِ", "segs": null, "full_uz": "Va uni Allohdan va oxirat uyidan qo'rqishni unutishga majbur qildi.", "note": null},
  {"num": 228, "time": "00:17:38,059 --> 00:17:42,079", "arabic": "اَلْعِصْمَةُ لَا تَكُونُ إِلَّا لِلْأَنْبِيَاءِ يَا شَافِعِيُّ", "segs": null, "full_uz": "Ismat (gunohdan pok bo'lish) faqat payg'ambarlarga xosdir, ey Shofi'iy.", "note": null},
  {"num": 229, "time": "00:17:42,079 --> 00:17:49,419", "arabic": "أَصْلَحَ اللَّهُ أَمِيرَ الْمُؤْمِنِينَ قَدْ عَلِمْنَا أَنَّهُ لَا يُظْلَمُ عِنْدَهُ أَحَدٌ", "segs": null, "full_uz": "Alloh mo'minlar amirini islohot qilsin, bilamizki, uning huzurida hech kimga zulm qilinmaydi.", "note": null},
  {"num": 230, "time": "00:17:49,419 --> 00:17:53,000", "arabic": "رَفَعَ اللَّهُ مَقَامَكَ يَا شَافِعِيُّ", "segs": null, "full_uz": "Alloh martabangni yuksaltirsin, ey Shofi'iy.", "note": null},
  {"num": 231, "time": "00:17:53,000 --> 00:18:02,579", "arabic": "لَقَدْ أَخْبَرَنِي قَاضِي الْقُضَاةِ أَنَّكَ أَخَذْتَ الْعِلْمَ عَلَى يَدِ الْإِمَامِ مَالِكِ بْنِ أَنَسٍ رَحِمَهُ اللَّهُ", "segs": null, "full_uz": "Bosh qozi menga siz ilmni imom Molik ibn Anas — Alloh unga rahmat qilsin — dan olganingizni aytdi.", "note": null},
  {"num": 232, "time": "00:18:05,279 --> 00:18:07,740", "arabic": "رَحِمَ اللَّهُ مَالِكًا", "segs": null, "full_uz": "Alloh Molikka rahmat qilsin.", "note": null},
  {"num": 233, "time": "00:18:07,740 --> 00:18:14,039", "arabic": "إِنَّهُ نَجْمُ الْعُلَمَاءِ وَزِينَةُ الْفُقَهَاءِ وَالْمُحَدِّثِينَ", "segs": null, "full_uz": "U olimlarning yulduzi, fuqaho va muhaddislarning ziynatidir.", "note": null},
  {"num": 234, "time": "00:18:14,039 --> 00:18:17,380", "arabic": "وَمَا أَحَدٌ آمَنُ مِنْ مَالِكٍ", "segs": null, "full_uz": "Molikdan ko'ra ishonchliroq hech kim yo'q.", "note": null},
  {"num": 235, "time": "00:18:17,380 --> 00:18:22,339", "arabic": "أَخْبِرْنِي عَنْ عِلْمِكَ بِكِتَابِ اللَّهِ يَا ابْنَ إِدْرِيسَ", "segs": null, "full_uz": "Menga Alloh kitobi haqidagi ilming to'g'risida so'zlab ber, ey Ibn Idris.", "note": null},
  {"num": 236, "time": "00:18:22,339 --> 00:18:27,420", "arabic": "عَنْ أَيِّ عُلُومِهِ تَسْأَلُنِي يَا أَمِيرَ الْمُؤْمِنِينَ؟", "segs": null, "full_uz": "Uning qaysi ilmlari haqida so'rayapsiz, ey mo'minlar amiri?", "note": null},
  {"num": 237, "time": "00:18:27,420 --> 00:18:32,259", "arabic": "عَنْ حِفْظِهِ فَقَدْ حَفِظْتُهُ وَوَعَيْتُهُ بَيْنَ جَنْبَيَّ", "segs": null, "full_uz": "Uni yodlash haqida — men uni yodlab, ko'nglimga joylab oldim.", "note": null},
  {"num": 238, "time": "00:18:32,259 --> 00:18:36,420", "arabic": "وَعَرَفْتُ وَقْفَهُ وَابْتِدَاءَهُ وَعَدَدَهُ", "segs": null, "full_uz": "Va uning to'xtash joylarini, boshlanishini va sonini bildim.", "note": null},
  {"num": 239, "time": "00:18:36,420 --> 00:18:47,420", "arabic": "وَعَرَفْتُ أَيْضًا مَكِّيَّهُ وَمَدَنِيَّهُ وَنَاسِخَهُ وَمَنْسُوخَهُ وَلَيْلِيَّهُ وَنَهَارِيَّهُ", "segs": null, "full_uz": "Va yana Makkiy va Madaniy oyatlarini, nosikh va mansuxini, kechasi va kunduzi nozil bo'lganlarini ham bildim.", "note": null},
  {"num": 240, "time": "00:18:47,420 --> 00:18:54,420", "arabic": "وَمَا خُوطِبَ مِنَ الْعَامِّ يُرَادُ بِهِ الْخَاصُّ وَمَا خُوطِبَ مِنَ الْعَامِّ يُرَادُ بِهِ الْعَامُّ", "segs": null, "full_uz": "Va umumiy shaklda kelib, xususiy ma'no nazarda tutilgan va umumiy shaklda kelib, umumiy ma'no nazarda tutilgan oyatlarni ham.", "note": "Qur'on ilmlaridan «om va xos» (umumiy va xususiy) tushunchasiga ishora."},
  {"num": 241, "time": "00:18:54,420 --> 00:19:01,420", "arabic": "وَاللَّهِ يَا ابْنَ إِدْرِيسَ لَقَدْ أَثْلَجْتَ صَدْرِي", "segs": null, "full_uz": "Alloh haqqi, ey Ibn Idris, ko'nglimni yorishtirding.", "note": "«أَثْلَجَ صَدْرَهُ» — birovni juda xursand qilish, ko'nglini yorishtirish ma'nosidagi ibora."},
  {"num": 242, "time": "00:19:01,420 --> 00:19:01,900", "arabic": "صَدْرِي", "segs": null, "full_uz": "Ko'nglimni.", "note": null},
  {"num": 243, "time": "00:19:01,900 --> 00:19:05,320", "arabic": "فَكَيْفَ عِلْمُكَ", "segs": null, "full_uz": "Xo'sh, ilming qanday...", "note": null},
  {"num": 244, "time": "00:19:05,320 --> 00:19:05,880", "arabic": "مِنَ النُّجُومِ؟", "segs": null, "full_uz": "...yulduzlar haqida-chi?", "note": null},
  {"num": 245, "time": "00:19:05,880 --> 00:19:08,840", "arabic": "إِنِّي", "segs": null, "full_uz": "Men...", "note": null},
  {"num": 246, "time": "00:19:08,840 --> 00:19:10,820", "arabic": "لَا أَعْرِفُ مِنْهَا", "segs": null, "full_uz": "...ulardan bilmayman.", "note": null},
  {"num": 247, "time": "00:19:10,820 --> 00:19:13,340", "arabic": "اَلْبَرِّيَّةَ وَالْبَحْرِيَّةَ وَالْجَبَلِيَّةَ", "segs": null, "full_uz": "Quruqlik, dengiz va tog' yulduzlarini.", "note": null},
  {"num": 250, "time": "00:19:16,300 --> 00:19:18,880", "arabic": "وَمَا يَجِبُ مَعْرِفَتُهُ", "segs": null, "full_uz": "Va bilish zarur bo'lgan narsalarni.", "note": null},
  {"num": 251, "time": "00:19:18,880 --> 00:19:22,680", "arabic": "وَالْأَنْسَابَ", "segs": null, "full_uz": "Va nasablarni.", "note": null},
  {"num": 252, "time": "00:19:22,680 --> 00:19:25,140", "arabic": "إِنِّي لَا أَعْرِفُ", "segs": null, "full_uz": "Men bilmayman.", "note": null},
  {"num": 253, "time": "00:19:25,140 --> 00:19:27,460", "arabic": "أَنْسَابَ اللِّئَامِ وَأَنْسَابَ", "segs": null, "full_uz": "Nokas kishilarning nasablarini va...", "note": null},
  {"num": 254, "time": "00:19:27,460 --> 00:19:28,120", "arabic": "اَلْكِرَامِ", "segs": null, "full_uz": "...oliyjanob kishilarning nasablarini.", "note": null},
  {"num": 255, "time": "00:19:28,120 --> 00:19:29,960", "arabic": "وَنَسَبِي", "segs": null, "full_uz": "Va o'z nasabimni.", "note": null},
  {"num": 256, "time": "00:19:29,960 --> 00:19:32,440", "arabic": "وَنَسَبَ أَمِيرِ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Va mo'minlar amirining nasabini.", "note": null},
  {"num": 257, "time": "00:19:32,440 --> 00:19:33,799", "arabic": "اَللَّهُ رَبِّي", "segs": null, "full_uz": "Alloh — mening Robbimdir.", "note": null},
  {"num": 258, "time": "00:19:33,799 --> 00:19:37,740", "arabic": "اَللَّهُ رَبِّي لَا أُشْرِكُ بِهِ أَحَدًا", "segs": null, "full_uz": "Alloh — mening Robbim, Unga hech kimni shirk keltirmayman.", "note": null},
  {"num": 259, "time": "00:19:37,740 --> 00:19:43,960", "arabic": "هَلْ مِنْ عِظَةٍ تَعِظُ بِهَا أَمِيرَ الْمُؤْمِنِينَ؟", "segs": null, "full_uz": "Mo'minlar amiriga bir nasihat qila olasizmi?", "note": null},
  {"num": 260, "time": "00:19:47,720 --> 00:19:50,100", "arabic": "دَعِ الْأَيَّامَ تَفْعَلْ مَا تَشَاءُ", "segs": null, "full_uz": "Kunlarni xohlagan ishini qilishga qo'yib ber.", "note": null},
  {"num": 261, "time": "00:19:50,100 --> 00:19:55,019", "arabic": "وَطِبْ نَفْسًا إِذَا حَكَمَ الْقَضَاءُ", "segs": null, "full_uz": "Va taqdir hukm qilganda, ko'ngling xotirjam bo'lsin.", "note": null},
  {"num": 262, "time": "00:19:55,019 --> 00:19:59,100", "arabic": "وَلَا تَجْزَعْ لِحَادِثَةِ اللَّيَالِي", "segs": null, "full_uz": "Va kechalar keltirgan voqealardan tashvishlanma.", "note": null},
  {"num": 263, "time": "00:19:59,960 --> 00:20:02,440", "arabic": "فَمَا لِحَوَادِثِ الدُّنْيَا بَقَاءٌ", "segs": null, "full_uz": "Chunki dunyo voqealarining davomiyligi yo'q.", "note": null},
  {"num": 264, "time": "00:20:02,440 --> 00:20:06,860", "arabic": "وَكُنْ رَجُلًا عَلَى الْأَهْوَالِ جَلْدًا", "segs": null, "full_uz": "Qo'rqinchli voqealarga bardoshli erkak bo'l.", "note": null},
  {"num": 265, "time": "00:20:06,860 --> 00:20:10,819", "arabic": "وَشِيمَتُكَ السَّمَاحَةُ وَالْوَفَاءُ", "segs": null, "full_uz": "Xulqing saxovat va vafodorlik bo'lsin.", "note": null},
  {"num": 266, "time": "00:20:10,819 --> 00:20:15,900", "arabic": "وَإِنْ كَثُرَتْ عُيُوبُكَ فِي الْبَرَايَا", "segs": null, "full_uz": "Agar odamlar oldida kamchiliklaring ko'p bo'lsa.", "note": null},
  {"num": 267, "time": "00:20:15,900 --> 00:20:19,920", "arabic": "وَسَرَّكَ أَنْ يَكُونَ لَهَا غِطَاءٌ", "segs": null, "full_uz": "Va ularni yashirish seni xursand qilsa.", "note": null},
  {"num": 268, "time": "00:20:19,920 --> 00:20:24,240", "arabic": "يُغَطَّى بِالسَّمَاحَةِ كُلُّ عَيْبٍ", "segs": null, "full_uz": "Har bir kamchilik saxovat bilan yopiladi.", "note": null},
  {"num": 269, "time": "00:20:24,240 --> 00:20:29,420", "arabic": "وَكَمْ عَيْبٍ يُغَطِّيهِ السَّخَاءُ", "segs": null, "full_uz": "Va qancha kamchilik saxiylik bilan yopiladi.", "note": null},
  {"num": 270, "time": "00:20:29,960 --> 00:20:35,640", "arabic": "يَا ابْنَ الرَّبِيعِ", "segs": null, "full_uz": "Ey Ibn Rabi.", "note": null},
  {"num": 271, "time": "00:20:35,640 --> 00:20:37,299", "arabic": "لَبَّيْكَ يَا مَوْلَايَ", "segs": null, "full_uz": "Labbay, xo'jayinim.", "note": null},
  {"num": 272, "time": "00:20:37,299 --> 00:20:41,579", "arabic": "هَذَا ابْنُ عَمِّ أَمِيرِ الْمُؤْمِنِينَ عِنْدَكَ", "segs": null, "full_uz": "Mana bu — mo'minlar amirining amakivachchasi, u sizning oldingizda.", "note": null},
  {"num": 273, "time": "00:20:41,579 --> 00:20:45,120", "arabic": "وَانْظُرْ لَهُ دَارًا يَسْكُنُهَا", "segs": null, "full_uz": "Unga turadigan uy toping.", "note": null},
  {"num": 274, "time": "00:20:45,120 --> 00:20:48,180", "arabic": "وَنَفَقَةً تُعِينُهُ عَلَى عَيْشِهِ", "segs": null, "full_uz": "Va turmushiga yordam beradigan nafaqa.", "note": null},
  {"num": 275, "time": "00:20:48,180 --> 00:20:51,740", "arabic": "وَأَطْلِقْ صَرَاحَةً رَفِيقَهُ", "segs": null, "full_uz": "Va uning hamrohini ochiqchasiga ozod qiling.", "note": null},
  {"num": 276, "time": "00:20:51,740 --> 00:20:54,100", "arabic": "فِي الْحَالِ يَا أَمِيرَ الْمُؤْمِنِينَ فِي الْحَالِ", "segs": null, "full_uz": "Hozirning o'zida, ey mo'minlar amiri, hozirning o'zida.", "note": null},
  {"num": 277, "time": "00:20:54,100 --> 00:20:57,620", "arabic": "جَزَاكَ اللَّهُ كُلَّ خَيْرٍ يَا أَمِيرَ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Alloh senga barcha yaxshiliklar bilan mukofot bersin, ey mo'minlar amiri.", "note": null},
  {"num": 278, "time": "00:20:57,620 --> 00:20:59,460", "arabic": "حَلَلْتَ أَهْلًا يَا شَافِعِيُّ", "segs": null, "full_uz": "Xush kelibsiz, ey Shofi'iy.", "note": null},
  {"num": 279, "time": "00:20:59,460 --> 00:21:12,000", "arabic": "يَا أَمِيرَ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Ey mo'minlar amiri.", "note": null},
  {"num": 280, "time": "00:21:12,000 --> 00:21:15,360", "arabic": "لِي عِنْدَكَ طَلَبٌ قَبْلَ أَنْ أَخْرُجَ؟", "segs": null, "full_uz": "Chiqishimdan oldin sizdan bir iltimosim bor.", "note": null},
  {"num": 281, "time": "00:21:15,360 --> 00:21:16,440", "arabic": "قُلْ يَا شَافِعِيُّ", "segs": null, "full_uz": "Ayt, ey Shofi'iy.", "note": null},
  {"num": 282, "time": "00:21:16,440 --> 00:21:19,120", "arabic": "وَبِإِذْنِ اللَّهِ طَلَبُكَ مُجَابٌ", "segs": null, "full_uz": "Alloh izni bilan, iltimosing qabul qilinadi.", "note": null},
  {"num": 283, "time": "00:21:19,120 --> 00:21:22,980", "arabic": "هَا أَنَا ذَا خَرَجْتُ مِنْ سِجْنِكَ", "segs": null, "full_uz": "Mana, men sizning zindoningizdan chiqdim.", "note": null},
  {"num": 284, "time": "00:21:22,980 --> 00:21:25,019", "arabic": "بَعْدَ أَنْ دَخَلْتُهُ مَظْلُومًا", "segs": null, "full_uz": "Unga mazlum holda kirganimdan keyin.", "note": null},
  {"num": 285, "time": "00:21:25,019 --> 00:21:27,819", "arabic": "فَمَنَّ اللَّهُ عَلَيَّ بِالْفَرَجِ", "segs": null, "full_uz": "Alloh menga najot in'om qildi.", "note": null},
  {"num": 286, "time": "00:21:27,819 --> 00:21:30,419", "arabic": "وَأَظْهَرَ بَرَاءَتِي لَكَ", "segs": null, "full_uz": "Va pokligimni sizga namoyon qildi.", "note": null},
  {"num": 287, "time": "00:21:30,419 --> 00:21:34,179", "arabic": "وَلَكِنْ أَخْشَى أَنَّ فِي سِجْنِكَ مَظْلُومِينَ", "segs": null, "full_uz": "Lekin zindoningizda mazlumlar bordir deb qo'rqaman.", "note": null},
  {"num": 288, "time": "00:21:34,179 --> 00:21:36,480", "arabic": "لَمْ يَبْلُغْهُمْ عَفْوُكَ", "segs": null, "full_uz": "Sizning avfingiz ularga yetmagan.", "note": null},
  {"num": 289, "time": "00:21:36,480 --> 00:21:39,019", "arabic": "وَلَمْ يَشْمَلْهُمْ صَفْحُكَ", "segs": null, "full_uz": "Va kechirimingiz ularni qamrab olmagan.", "note": null},
  {"num": 290, "time": "00:21:39,019 --> 00:21:42,960", "arabic": "فَتَفَقَّدْ أَحْوَالَهُمْ يَا أَمِيرَ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Ularning holidan xabar oling, ey mo'minlar amiri.", "note": null},
  {"num": 291, "time": "00:21:52,299 --> 00:21:54,179", "arabic": "يَا شَافِعِيُّ", "segs": null, "full_uz": "Ey Shofi'iy.", "note": null},
  {"num": 292, "time": "00:21:54,180 --> 00:22:01,560", "arabic": "هَارُونُ الرَّشِيدُ لَا يَرْضَى أَبَدًا أَنْ يُسْجَنَ عِنْدَهُ أَحَدٌ ظُلْمًا", "segs": null, "full_uz": "Horun ar-Rashid hech qachon kimningdir uning huzurida zulm bilan qamalishiga rozi bo'lmaydi.", "note": null},
  {"num": 293, "time": "00:22:01,560 --> 00:22:07,279", "arabic": "فَإِنْ كُنْتَ تَعْرِفُ أَسْمَاءَ بَعْضِ هَؤُلَاءِ نَظَرْنَا فِي أَمْرِهِمْ", "segs": null, "full_uz": "Agar ulardan ba'zilarining ismlarini bilsangiz, ishlarini ko'rib chiqamiz.", "note": null},
  {"num": 294, "time": "00:22:07,279 --> 00:22:11,519", "arabic": "أَنَا لَا أَعْرِفُهُمْ يَا أَمِيرَ الْمُؤْمِنِينَ لَا أَعْرِفُهُمْ", "segs": null, "full_uz": "Men ularni bilmayman, ey mo'minlar amiri, bilmayman.", "note": null},
  {"num": 295, "time": "00:22:11,519 --> 00:22:16,420", "arabic": "وَلَكِنْ حَارِسَ زِنْزَانَتِي يَعْرِفُ قِصَصًا كَثِيرَةً عَنْهُمْ", "segs": null, "full_uz": "Lekin mening zindonim qorovuli ular haqida ko'p voqealarni biladi.", "note": null},
  {"num": 296, "time": "00:22:16,420 --> 00:22:18,000", "arabic": "لَيْتَكَ تَسْمَعُهَا", "segs": null, "full_uz": "Koshki ularni eshitsangiz.", "note": null},
  {"num": 297, "time": "00:22:18,000 --> 00:22:19,320", "arabic": "وَاللَّهِ", "segs": null, "full_uz": "Alloh haqqi.", "note": null},
  {"num": 298, "time": "00:22:19,320 --> 00:22:23,720", "arabic": "إِنِّي لَا أَقْصِدُ مِنْ وَرَاءِ هَذِهِ النَّصِيحَةِ", "segs": null, "full_uz": "Men bu nasihat ortidan hech narsani ko'zlamayman.", "note": null},
  {"num": 299, "time": "00:22:23,720 --> 00:22:26,440", "arabic": "إِلَّا رَفْعَ الظُّلْمِ عَنْ كُلِّ مَظْلُومٍ", "segs": null, "full_uz": "Faqat har bir mazlumdan zulmni ko'tarishdan boshqa.", "note": null},
  {"num": 300, "time": "00:22:26,440 --> 00:22:32,420", "arabic": "سَنَأْتِي بِهَذَا الْحَارِسِ وَنَسْمَعُ مِنْهُ كُلَّ مَا عِنْدَهُ", "segs": null, "full_uz": "Bu qorovulni olib kelib, undan bor gaplarni eshitamiz.", "note": null},
  {"num": 301, "time": "00:22:32,420 --> 00:22:34,420", "arabic": "أَعِدُكَ بِذَلِكَ", "segs": null, "full_uz": "Senga shuni va'da qilaman.", "note": null},
  {"num": 302, "time": "00:22:34,420 --> 00:22:38,279", "arabic": "جَزَاكَ اللَّهُ كُلَّ خَيْرٍ يَا أَمِيرَ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Alloh senga barcha yaxshiliklar bilan mukofot bersin, ey mo'minlar amiri.", "note": null},
  {"num": 303, "time": "00:22:38,279 --> 00:22:41,000", "arabic": "هَلْ لَدَيْكَ طَلَبٌ آخَرُ؟", "segs": null, "full_uz": "Boshqa iltimosing bormi?", "note": null},
  {"num": 304, "time": "00:22:41,000 --> 00:22:41,339", "arabic": "لَا", "segs": null, "full_uz": "Yo'q.", "note": null},
  {"num": 305, "time": "00:22:41,339 --> 00:22:43,620", "arabic": "لَا أُرِيدُ شَيْئًا", "segs": null, "full_uz": "Hech narsa xohlamayman.", "note": null},
  {"num": 306, "time": "00:22:43,620 --> 00:22:46,980", "arabic": "إِلَّا أَنْ أَرَاكَ بِخَيْرٍ يَا مَوْلَايَ", "segs": null, "full_uz": "Faqat sizni sog'-salomat ko'rishdan boshqa, xo'jayinim.", "note": null},
  {"num": 307, "time": "00:22:46,980 --> 00:22:48,200", "arabic": "يَا ابْنَ الرَّبِيعِ", "segs": null, "full_uz": "Ey Ibn Rabi.", "note": null},
  {"num": 308, "time": "00:22:48,200 --> 00:22:48,860", "arabic": "مَوْلَايَ", "segs": null, "full_uz": "Xo'jayinim.", "note": null},
  {"num": 309, "time": "00:22:48,860 --> 00:22:52,039", "arabic": "نَفِّذْ مَا طَلَبْتُهُ مِنْكَ فِي الْحَالِ", "segs": null, "full_uz": "Sendan so'ragan narsamni hoziroq bajar.", "note": null},
  {"num": 310, "time": "00:22:52,039 --> 00:22:54,279", "arabic": "أَمْرُكَ يَا أَمِيرَ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Xo'p bo'ladi, ey mo'minlar amiri.", "note": null},
  {"num": 311, "time": "00:22:54,279 --> 00:22:56,440", "arabic": "تَفَضَّلْ أَيُّهَا الشَّافِعِيُّ", "segs": null, "full_uz": "Marhamat, ey Shofi'iy.", "note": null},
  {"num": 312, "time": "00:22:56,440 --> 00:22:57,879", "arabic": "اَلسَّلَامُ عَلَيْكُمْ", "segs": null, "full_uz": "Assalomu alaykum.", "note": null},
  {"num": 313, "time": "00:22:57,879 --> 00:22:59,180", "arabic": "عَلَيْكُمُ السَّلَامُ", "segs": null, "full_uz": "Va sizga ham salom.", "note": null},
  {"num": 314, "time": "00:22:59,180 --> 00:23:23,060", "arabic": "فَسَأَلَ الصَّحَابَةُ", "segs": null, "full_uz": "Sahobalar so'radilar.", "note": null},
  {"num": 315, "time": "00:23:23,060 --> 00:23:24,900", "arabic": "يَا رَسُولَ اللَّهِ", "segs": null, "full_uz": "Ey Allohning Rasuli.", "note": null},
  {"num": 316, "time": "00:23:24,900 --> 00:23:28,539", "arabic": "هَلْ نَرَى اللَّهَ عَزَّ وَجَلَّ يَوْمَ الْقِيَامَةِ؟", "segs": null, "full_uz": "Qiyomat kuni Allohni ko'ramizmi?", "note": null},
  {"num": 317, "time": "00:23:28,539 --> 00:23:32,740", "arabic": "قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ", "segs": null, "full_uz": "Rasululloh (sollallohu alayhi va sallam) aytdilar.", "note": null},
  {"num": 318, "time": "00:23:32,740 --> 00:23:38,420", "arabic": "هَلْ تَرَوْنَ الْقَمَرَ لَيْلَةَ الْبَدْرِ لَيْسَ فِي السَّمَاءِ سَحَابَةٌ؟", "segs": null, "full_uz": "Osmonda bulut bo'lmagan to'lin oy kechasida oyni ko'rasizlarmi?", "note": null},
  {"num": 319, "time": "00:23:38,420 --> 00:23:39,859", "arabic": "قَالُوا نَعَمْ", "segs": null, "full_uz": "Ha, dedilar.", "note": null},
  {"num": 320, "time": "00:23:39,859 --> 00:23:44,000", "arabic": "قَالَ فَوَالَّذِي نَفْسِي بِيَدِهِ", "segs": null, "full_uz": "Aytdilar: jonim qo'lida bo'lgan Zot bilan qasamki.", "note": null},
  {"num": 321, "time": "00:23:44,000 --> 00:23:46,859", "arabic": "لَتَرَوُنَّ اللَّهَ عَزَّ وَجَلَّ", "segs": null, "full_uz": "Albatta Allohni ko'rasizlar.", "note": null},
  {"num": 322, "time": "00:23:46,859 --> 00:23:51,599", "arabic": "كَمَا تَرَوْنَ الْقَمَرَ لَا تُضَامُّونَ فِي رُؤْيَتِهِ", "segs": null, "full_uz": "Oyni ko'rganingizdek, uni ko'rishda bir-biringizga xalaqit bermaysizlar.", "note": null},
  {"num": 323, "time": "00:23:51,599 --> 00:23:54,899", "arabic": "وَمَعْنَى لَا تُضَامُّونَ فِي رُؤْيَتِهِ", "segs": null, "full_uz": "«Uni ko'rishda bir-biringizga xalaqit bermaysizlar» so'zining ma'nosi.", "note": null},
  {"num": 324, "time": "00:23:54,899 --> 00:23:57,399", "arabic": "أَيْ لَا يَنَالُكُمْ ظُلْمٌ", "segs": null, "full_uz": "Ya'ni sizga hech qanday adolatsizlik yetmaydi.", "note": null},
  {"num": 325, "time": "00:23:57,400 --> 00:24:02,380", "arabic": "وَتَسْتَوُونَ كُلُّكُمْ فِي رُؤْيَةِ اللَّهِ سُبْحَانَهُ وَتَعَالَى", "segs": null, "full_uz": "Va hammangiz Allohni ko'rishda tengsizlar.", "note": null},
  {"num": 326, "time": "00:24:02,380 --> 00:24:06,340", "arabic": "وَبِمِثْلِ هَذِهِ النُّصُوصِ الصَّحِيحَةِ", "segs": null, "full_uz": "Va shunga o'xshash sahih matnlar bilan.", "note": null},
  {"num": 327, "time": "00:24:06,340 --> 00:24:11,960", "arabic": "يَسْتَدِلُّ أَهْلُ السُّنَّةِ عَلَى رُؤْيَةِ اللَّهِ سُبْحَانَهُ وَتَعَالَى فِي الْآخِرَةِ", "segs": null, "full_uz": "Ahli sunna oxiratda Allohni ko'rishga dalil keltiradi.", "note": null},
  {"num": 328, "time": "00:24:11,960 --> 00:24:15,420", "arabic": "خِلَافًا لِلْمُعْتَزِلَةِ وَأَتْبَاعِهِمْ", "segs": null, "full_uz": "Mu'taziliylar va ularning izdoshlariga qarama-qarshi o'laroq.", "note": null},
  {"num": 329, "time": "00:24:18,420 --> 00:24:23,220", "arabic": "أَلَا تَرَوْنَ مَعِي أَنَّ مَتْنَ الْحَدِيثِ الَّذِي ذَكَرَهُ شَيْخُنَا الْيَوْمَ", "segs": null, "full_uz": "Bugun ustozimiz zikr qilgan hadisning matni...", "note": null},
  {"num": 330, "time": "00:24:23,220 --> 00:24:25,580", "arabic": "يَتَعَارَضُ مَعَ صَرِيحِ الْقُرْآنِ", "segs": null, "full_uz": "...Qur'onning aniq matniga zid kelayotganini men bilan birga ko'rmayapsizlarmi?", "note": null},
  {"num": 331, "time": "00:24:25,579 --> 00:24:28,939", "arabic": "فَقَدْ قَالَ مُوسَى عَلَيْهِ السَّلَامُ", "segs": null, "full_uz": "Chunki Muso alayhissalom aytgan edilar.", "note": null},
  {"num": 332, "time": "00:24:28,939 --> 00:24:31,799", "arabic": "رَبِّ أَرِنِي أَنْظُرْ إِلَيْكَ", "segs": null, "full_uz": "Robbim, menga O'zingni ko'rsat, senga qarayin.", "note": "Qur'ondagi (A'rof, 143-oyat) ma'nosiga ishora."},
  {"num": 333, "time": "00:24:31,799 --> 00:24:34,879", "arabic": "فَأَجَابَهُ تَعَالَى لَنْ تَرَانِي", "segs": null, "full_uz": "Alloh taolo unga: «Meni aslo ko'ra olmaysan», deb javob berdi.", "note": null},
  {"num": 334, "time": "00:24:34,879 --> 00:24:37,299", "arabic": "غَفَرَ اللَّهُ لَكَ يَا أَبَا عَبْدِ الرَّحْمَنِ", "segs": null, "full_uz": "Alloh senga mag'firat qilsin, ey Abu Abdurahmon.", "note": null},
  {"num": 335, "time": "00:24:37,299 --> 00:24:40,339", "arabic": "تَسْتَدِلُّ بِهَذِهِ الْآيَةِ إِلَى نَفْيِ الرُّؤْيَةِ", "segs": null, "full_uz": "Sen bu oyat bilan Allohni ko'rishning yo'qligiga dalil keltiryapsan.", "note": null},
  {"num": 336, "time": "00:24:40,339 --> 00:24:42,799", "arabic": "وَهِيَ حُجَّةٌ عَلَيْكَ لَا حُجَّةٌ لَكَ", "segs": null, "full_uz": "Holbuki, bu senga qarshi dalildir, sening foydangga emas.", "note": null},
  {"num": 337, "time": "00:24:42,799 --> 00:24:46,639", "arabic": "حُجَّةٌ عَلَيْكَ؟ كَيْفَ ذَلِكَ؟", "segs": null, "full_uz": "Menga qarshi dalilmi? Bu qanday bo'ladi?", "note": null},
  {"num": 338, "time": "00:24:46,639 --> 00:24:48,859", "arabic": "اَلْمَقْصُودُ بِقَوْلِهِ تَعَالَى لَنْ تَرَانِي", "segs": null, "full_uz": "Allohning «Meni aslo ko'ra olmaysan» degan so'zidan maqsad.", "note": null},
  {"num": 339, "time": "00:24:48,859 --> 00:24:51,439", "arabic": "يَعْنِي فِي الدُّنْيَا لَنْ تَثْبُتَ الرُّؤْيَةُ", "segs": null, "full_uz": "Ya'ni, dunyoda ko'rish sodir bo'lmaydi, degani.", "note": null},
  {"num": 340, "time": "00:24:51,439 --> 00:24:52,779", "arabic": "أَمَّا فِي الْآخِرَةِ", "segs": null, "full_uz": "Oxiratga kelsak esa.", "note": null},
  {"num": 341, "time": "00:24:52,779 --> 00:24:56,319", "arabic": "فَقَدْ أَشَارَ إِلَى تَحَقُّقِ الرُّؤْيَةِ صَرِيحُ الْقُرْآنِ الْكَرِيمِ", "segs": null, "full_uz": "Qur'oni Karimning aniq matni ko'rishning sodir bo'lishiga ishora qilgan.", "note": null},
  {"num": 342, "time": "00:24:56,319 --> 00:24:57,460", "arabic": "قَالَ تَعَالَى", "segs": null, "full_uz": "Alloh taolo aytdi.", "note": null},
  {"num": 343, "time": "00:24:57,460 --> 00:25:01,660", "arabic": "وُجُوهٌ يَوْمَئِذٍ نَاضِرَةٌ إِلَى رَبِّهَا نَاظِرَةٌ", "segs": null, "full_uz": "O'sha kuni yuzlar nurli bo'lib, Robbisiga qarab turadi.", "note": "Qur'ondagi (Qiyoma, 22-23-oyatlar) iqtibos."},
  {"num": 344, "time": "00:25:01,660 --> 00:25:04,099", "arabic": "لَا أَدْرِي", "segs": null, "full_uz": "Bilmayman.", "note": null},
  {"num": 345, "time": "00:25:04,099 --> 00:25:06,299", "arabic": "رُبَّمَا تَكُونُ عَلَى حَقٍّ", "segs": null, "full_uz": "Balki haqsan.", "note": null},
  {"num": 346, "time": "00:25:06,299 --> 00:25:08,579", "arabic": "أَسْتَوْدِعُكُمُ اللَّهَ", "segs": null, "full_uz": "Sizlarni Allohga omonat qildim.", "note": null},
  {"num": 347, "time": "00:25:08,579 --> 00:25:09,899", "arabic": "فِي أَمَانِ اللَّهِ", "segs": null, "full_uz": "Alloh amonatida bo'ling.", "note": null},
  {"num": 349, "time": "00:25:10,720 --> 00:25:13,799", "arabic": "هَلْ تَذْهَبُ مَعِي إِلَى دُكَّانِ مَرْوَانَ؟", "segs": null, "full_uz": "Marvonning do'koniga men bilan borasanmi?", "note": null},
  {"num": 350, "time": "00:25:13,799 --> 00:25:17,420", "arabic": "لَا، اذْهَبْ أَنْتَ، لَدَيَّ شَيْءٌ أَفْعَلُهُ", "segs": null, "full_uz": "Yo'q, sen bor, mening qiladigan ishim bor.", "note": null},
  {"num": 351, "time": "00:25:17,420 --> 00:25:21,619", "arabic": "اَلْحَقُّ يَا شَيْخِي أَنَّنِي لَمْ أَسْتَطِعِ الرَّدَّ عَلَيْهِ", "segs": null, "full_uz": "Rostini aytsam, ustozim, unga javob bera olmadim.", "note": null},
  {"num": 352, "time": "00:25:21,619 --> 00:25:23,759", "arabic": "لَعَلَّكَ خِفْتَ؟", "segs": null, "full_uz": "Balki qo'rqdingmi?", "note": null},
  {"num": 353, "time": "00:25:23,759 --> 00:25:24,679", "arabic": "لَا لَمْ أَخَفْ", "segs": null, "full_uz": "Yo'q, qo'rqmadim.", "note": null},
  {"num": 354, "time": "00:25:24,679 --> 00:25:28,079", "arabic": "وَلَكِنَّكَ لَا تَعْرِفُ ابْنَ حَنْبَلٍ هَذَا", "segs": null, "full_uz": "Lekin sen bu Ibn Hanbalni bilmaysan.", "note": null},
  {"num": 355, "time": "00:25:28,079 --> 00:25:31,399", "arabic": "إِنَّهُ مِنْ خِيَرَةِ طَلَبَةِ الْعِلْمِ", "segs": null, "full_uz": "U ilm talabalarining eng yaxshilaridan.", "note": null},
  {"num": 356, "time": "00:25:31,399 --> 00:25:35,239", "arabic": "حَافِظٌ لِحَدِيثِ رَسُولِ اللَّهِ وَاسِعُ الِاطِّلَاعِ", "segs": null, "full_uz": "Rasululloh hadisini yodlagan, keng bilimli.", "note": null},
  {"num": 357, "time": "00:25:35,239 --> 00:25:38,619", "arabic": "صَاحِبُ حُجَّةٍ وَلَا يَتَكَلَّمُ إِلَّا بِدَلِيلٍ", "segs": null, "full_uz": "Dalilli odam, faqat dalil bilan gapiradi.", "note": null},
  {"num": 358, "time": "00:25:39,839 --> 00:25:42,500", "arabic": "خَشِيتُ أَنْ لَا أَكُونَ لَهُ نِدًّا فِي الْمُحَاوَرَةِ", "segs": null, "full_uz": "Munozarada unga teng kela olmasligimdan qo'rqdim.", "note": null},
  {"num": 359, "time": "00:25:42,500 --> 00:25:43,799", "arabic": "فَسَكَتُّ", "segs": null, "full_uz": "Shuning uchun jim turdim.", "note": null},
  {"num": 360, "time": "00:25:43,799 --> 00:25:46,619", "arabic": "أَحَسَنٌ أَنَّكَ فَعَلْتَ؟", "segs": null, "full_uz": "Yaxshi qilibsanmi?", "note": null},
  {"num": 361, "time": "00:25:48,619 --> 00:25:51,000", "arabic": "لَا أَكْتُمُكَ سِرًّا يَا شَيْخِي", "segs": null, "full_uz": "Sendan sirni yashirmayman, ustozim.", "note": null},
  {"num": 362, "time": "00:25:51,000 --> 00:25:54,920", "arabic": "أَنَّ كَلَامَ ابْنِ حَنْبَلٍ وَقَعَ مِنِّي مَوْقِعًا حَسَنًا", "segs": null, "full_uz": "Ibn Hanbalning gapi menga yoqdi.", "note": null},
  {"num": 363, "time": "00:25:54,920 --> 00:26:00,920", "arabic": "كَانَتْ حُجَجُهُ فِي إِثْبَاتِ وُقُوعِ رُؤْيَةِ اللَّهِ تَعَالَى فِي الْآخِرَةِ مُقْنِعَةً", "segs": null, "full_uz": "Oxiratda Allohni ko'rish sodir bo'lishini isbotlashdagi dalillari ishonarli edi.", "note": null},
  {"num": 364, "time": "00:26:00,920 --> 00:26:03,619", "arabic": "بَلْ مُقْنِعَةٌ جِدًّا", "segs": null, "full_uz": "Balki juda ham ishonarli.", "note": null},
  {"num": 365, "time": "00:26:03,619 --> 00:26:06,000", "arabic": "أَيَّةَ آيَةٍ تَقْصِدُ؟", "segs": null, "full_uz": "Qaysi oyatni nazarda tutyapsan?", "note": null},
  {"num": 366, "time": "00:26:06,920 --> 00:26:10,039", "arabic": "مِمَّا احْتَجَّ بِهِ قَوْلُهُ تَعَالَى", "segs": null, "full_uz": "U dalil sifatida keltirgan narsalardan biri Alloh taoloning so'zi.", "note": null},
  {"num": 367, "time": "00:26:10,039 --> 00:26:15,799", "arabic": "وُجُوهٌ يَوْمَئِذٍ نَاضِرَةٌ إِلَى رَبِّهَا نَاظِرَةٌ", "segs": null, "full_uz": "O'sha kuni yuzlar nurli bo'lib, Robbisiga qarab turadi.", "note": "Qur'ondagi (Qiyoma, 22-23-oyatlar) iqtibos."},
  {"num": 368, "time": "00:26:21,000 --> 00:26:27,039", "arabic": "لَا أَحْسَبُ بَدْرًا إِلَّا أَخْطَأَ فِي فَهْمِ الْآيَةِ الْكَرِيمَةِ", "segs": null, "full_uz": "Menimcha, Badr bu oyatni tushunishda xato qilgan.", "note": null},
  {"num": 369, "time": "00:26:27,039 --> 00:26:30,839", "arabic": "وَلَوْلَا أَنَّنَا مَأْمُورُونَ بِحُسْنِ الظَّنِّ بِإِخْوَانِنَا مِنَ الْمُسْلِمِينَ", "segs": null, "full_uz": "Agar musulmon birodarlarimizga yaxshi gumon qilishga buyurilmaganimizda.", "note": null},
  {"num": 370, "time": "00:26:30,839 --> 00:26:33,779", "arabic": "لَقُلْتُ أَنَّهُ يُرَدِّدُ كَلَامَ الْمُعْتَزِلَةِ لَا أَكْثَرَ", "segs": null, "full_uz": "Mu'taziliylarning gapini takrorlayapti, xolos, deb aytardim.", "note": null},
  {"num": 371, "time": "00:26:33,779 --> 00:26:37,319", "arabic": "صَدِيقُكَ عَلَى حَظٍّ وَافِرٍ مِنَ الصَّوَابِ", "segs": null, "full_uz": "Do'sting to'g'rilikdan katta ulushga ega.", "note": null},
  {"num": 372, "time": "00:26:37,319 --> 00:26:42,039", "arabic": "كَيْفَ ذَلِكَ يَا ابْنَ أَبِي دُؤَادٍ؟", "segs": null, "full_uz": "Bu qanday bo'ladi, Ibn Abi Duod?", "note": null},
  {"num": 373, "time": "00:26:42,599 --> 00:26:47,900", "arabic": "اَللَّهُ عَزَّ وَجَلَّ لَا يَحُدُّهُ مَكَانٌ وَلَا يُحِيطُ بِهِ زَمَانٌ", "segs": null, "full_uz": "Alloh — azza va jalla — hech qanday makon Uni cheklamaydi va zamon Uni qamrab olmaydi.", "note": null},
  {"num": 374, "time": "00:26:47,900 --> 00:26:52,040", "arabic": "وَلَوْ أَثْبَتْنَا رُؤْيَةَ الْمُؤْمِنِينَ لِلَّهِ فِي الْآخِرَةِ", "segs": null, "full_uz": "Agar biz mo'minlarning oxiratda Allohni ko'rishini isbotlasak.", "note": null},
  {"num": 375, "time": "00:26:52,040 --> 00:26:55,500", "arabic": "فَهَذَا يَعْنِي أَنَّ لِلَّهِ جِسْمًا مَحْدُودًا بِمَكَانٍ", "segs": null, "full_uz": "Bu Allohning makon bilan chegaralangan jismi bor, degani bo'ladi.", "note": null},
  {"num": 376, "time": "00:26:55,500 --> 00:26:57,840", "arabic": "تَعَالَى اللَّهُ عَنْ ذَلِكَ عُلُوًّا كَبِيرًا", "segs": null, "full_uz": "Alloh bundan yuksak va ulug'dir.", "note": null},
  {"num": 377, "time": "00:26:57,840 --> 00:27:00,519", "arabic": "أَمَّا قَوْلُهُ تَعَالَى", "segs": null, "full_uz": "Alloh taoloning so'ziga kelsak.", "note": null},
  {"num": 378, "time": "00:27:00,519 --> 00:27:04,820", "arabic": "وُجُوهٌ يَوْمَئِذٍ نَاضِرَةٌ إِلَى رَبِّهَا نَاظِرَةٌ", "segs": null, "full_uz": "O'sha kuni yuzlar nurli bo'lib, Robbisiga qarab turadi.", "note": null},
  {"num": 379, "time": "00:27:04,820 --> 00:27:09,460", "arabic": "فَالنَّظَرُ هُنَا لَا يَقْتَضِي الرُّؤْيَةَ كَمَا قَالَ صَدِيقُكُمْ", "segs": null, "full_uz": "Bu yerdagi 'qarash' do'stingiz aytgandek 'ko'rish'ni taqozo qilmaydi.", "note": null},
  {"num": 380, "time": "00:27:09,460 --> 00:27:11,759", "arabic": "وَإِنَّمَا الْمَقْصُودُ بِهِ الْإِمْهَالُ", "segs": null, "full_uz": "Aksincha, undan maqsad — muhlat berish.", "note": null},
  {"num": 381, "time": "00:27:11,759 --> 00:27:13,460", "arabic": "كَقَوْلِهِ تَعَالَى", "segs": null, "full_uz": "Alloh taoloning so'zidagidek.", "note": null},
  {"num": 382, "time": "00:27:13,460 --> 00:27:18,600", "arabic": "خَالِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنْظَرُونَ", "segs": null, "full_uz": "Unda abadiy qolgan holda, azob ulardan yengillashtirilmaydi va ularga muhlat ham berilmaydi.", "note": "Qur'ondagi (Baqara, 162-oyat) iqtibos."},
  {"num": 383, "time": "00:27:18,600 --> 00:27:20,019", "arabic": "أَيْ لَا يُمْهَلُونَ", "segs": null, "full_uz": "Ya'ni ularga muhlat berilmaydi.", "note": null},
  {"num": 384, "time": "00:27:20,019 --> 00:27:25,160", "arabic": "فَيَكُونُ النَّظَرُ بِمَعْنَى الِانْتِظَارِ وَلَيْسَ بِمَعْنَى الرُّؤْيَةِ رُؤْيَةِ الْعَيْنِ", "segs": null, "full_uz": "Demak, 'nazar' — kutish ma'nosida, ko'z bilan ko'rish ma'nosida emas.", "note": null},
  {"num": 385, "time": "00:27:25,160 --> 00:27:29,400", "arabic": "وَهَذَا الْقَوْلُ أَحْرَى بِتَنْزِيهِ اللَّهِ عَنِ التَّجْسِيمِ", "segs": null, "full_uz": "Bu fikr Allohni jismlashtirishdan pok deb bilishga ko'proq mos keladi.", "note": null},
  {"num": 386, "time": "00:27:29,400 --> 00:27:35,579", "arabic": "أَعُوذُ بِاللَّهِ مِنْ مَقَالَةِ السُّوءِ هَذِهِ", "segs": null, "full_uz": "Bu yomon so'zdan Allohga sig'inaman.", "note": null},
  {"num": 387, "time": "00:27:35,579 --> 00:27:38,059", "arabic": "هَذَا لَيٌّ لِأَعْنَاقِ النُّصُوصِ يَا ابْنَ أَبِي دُؤَادٍ", "segs": null, "full_uz": "Bu — matnlarning bo'ynini burish, ey Ibn Abi Duod.", "note": "«لَيُّ أَعْنَاقِ النُّصُوصِ» — matn ma'nosini zo'rlab, o'z foydasiga burib talqin qilish ma'nosidagi ibora."},
  {"num": 388, "time": "00:27:38,059 --> 00:27:39,940", "arabic": "وَخُرُوجًا بِالْكَلَامِ عَنْ ظَاهِرِهِ", "segs": null, "full_uz": "Va so'zni o'z zohiriy ma'nosidan chiqarish.", "note": null},
  {"num": 389, "time": "00:27:39,940 --> 00:27:42,019", "arabic": "لَمْ يَقُلْ بِذَلِكَ أَحَدٌ مِنَ السَّلَفِ", "segs": null, "full_uz": "Bu haqda salafdan hech kim aytmagan.", "note": null},
  {"num": 390, "time": "00:27:42,019 --> 00:27:44,720", "arabic": "لَا بَلْ فِيهِ مِنَ التَّهَافُتِ مَا لَا يَخْفَى", "segs": null, "full_uz": "Yo'q, aksincha, unda yashirin bo'lmagan nomuvofiqlik bor.", "note": null},
  {"num": 391, "time": "00:27:44,720 --> 00:27:46,900", "arabic": "هَدِّئْ مِنْ رَوْعِكَ يَا ابْنَ نُوحٍ", "segs": null, "full_uz": "Xotirjam bo'l, ey Ibn Nuh.", "note": null},
  {"num": 392, "time": "00:27:46,900 --> 00:27:49,599", "arabic": "هَدِّئْ مِنْ رَوْعِكَ يَا أَخِي", "segs": null, "full_uz": "Xotirjam bo'l, ukam.", "note": null},
  {"num": 393, "time": "00:27:49,599 --> 00:27:52,279", "arabic": "اِجْلِسْ وَدَعْنِي أَسْمَعْ رَأْيَكَ", "segs": null, "full_uz": "O'tir va fikringni eshitishimga ijozat ber.", "note": null},
  {"num": 394, "time": "00:27:52,279 --> 00:27:53,759", "arabic": "أَسْتَغْفِرُ اللَّهَ", "segs": null, "full_uz": "Allohdan mag'firat so'rayman.", "note": null},
  {"num": 395, "time": "00:27:53,759 --> 00:27:55,819", "arabic": "أَسْتَغْفِرُ اللَّهَ الْعَلِيَّ الْعَظِيمَ", "segs": null, "full_uz": "Ulug' va oliy Allohdan mag'firat so'rayman.", "note": null},
  {"num": 396, "time": "00:27:55,819 --> 00:28:03,240", "arabic": "أَوَّلًا مَنْ قَالَ إِنَّ النَّظَرَ لَا يَقْتَضِي الرُّؤْيَا؟", "segs": null, "full_uz": "Avvalo, 'nazar' ko'rishni taqozo qilmaydi, deb kim aytdi?", "note": null},
  {"num": 397, "time": "00:28:03,240 --> 00:28:07,960", "arabic": "ثُمَّ انْظُرْ إِلَى قَوْلِهِ تَعَالَى بَعْدَ بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ", "segs": null, "full_uz": "So'ngra, Bismillahir Rohmanir Rohiymdan keyingi Alloh taoloning so'ziga qara.", "note": null},
  {"num": 398, "time": "00:28:07,960 --> 00:28:15,240", "arabic": "وَإِذْ فَرَقْنَا بِكُمُ الْبَحْرَ فَأَنْجَيْنَاكُمْ وَأَغْرَقْنَا آلَ فِرْعَوْنَ وَأَنْتُمْ تَنْظُرُونَ", "segs": null, "full_uz": "Va o'shanda dengizni ikkiga ajratib, sizlarni qutqargan va Fir'avn xalqini g'arq qilgan edik, siz esa qarab turgan edinglar.", "note": "Qur'ondagi (Baqara, 50-oyat) iqtibos."},
  {"num": 399, "time": "00:28:15,240 --> 00:28:17,920", "arabic": "ثُمَّ إِلَى قَوْلِهِ تَعَالَى", "segs": null, "full_uz": "So'ngra Alloh taoloning yana bir so'ziga.", "note": null},
  {"num": 400, "time": "00:28:17,920 --> 00:28:23,059", "arabic": "قَدْ خَلَتْ مِنْ قَبْلِكُمْ سُنَنٌ فَسِيرُوا فِي الْأَرْضِ فَانْظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ", "segs": null, "full_uz": "Sizlardan oldin ham shunday qonuniyatlar o'tgan; yer yuzida sayr qilinglar va yolg'onchilarning oqibati qanday bo'lganini ko'ringlar.", "note": "Qur'ondagi (Ol Imron, 137-oyat) ma'nosiga ishora."},
  {"num": 401, "time": "00:28:23,059 --> 00:28:27,279", "arabic": "وَالْآيَاتُ فِي ذَلِكَ كَثِيرَةٌ وَكُلُّهَا تَقْتَضِي الرُّؤْيَةَ", "segs": null, "full_uz": "Bu haqdagi oyatlar ko'p, va ularning barchasi ko'rishni taqozo qiladi.", "note": null},
  {"num": 402, "time": "00:28:27,279 --> 00:28:32,700", "arabic": "أَمَّا الْقَوْلُ إِنَّ مَعْنَى قَوْلِهِ تَعَالَى إِلَى رَبِّهَا نَاظِرَةٌ يَعْنِي مُنْتَظِرَةٌ", "segs": null, "full_uz": "Alloh taoloning «Robbisiga qarab turadi» so'zi «kutayotgan» degani, deyilishiga kelsak.", "note": null},
  {"num": 403, "time": "00:28:32,700 --> 00:28:34,620", "arabic": "فَهَذَا جَهْلٌ فِي لُغَةِ الْعَرَبِ", "segs": null, "full_uz": "Bu arab tili bo'yicha bilimsizlikdir.", "note": null},
  {"num": 404, "time": "00:28:34,619 --> 00:28:38,459", "arabic": "فَقَدْ خَلَطُوا بَيْنَ نَظَرْتُ إِلَى الشَّيْءِ وَنَظَرْتُ لِلشَّيْءِ", "segs": null, "full_uz": "Ular «narsaga qaradim» va «narsa uchun kutdim» iboralarini aralashtirib yuborishgan.", "note": null},
  {"num": 405, "time": "00:28:38,459 --> 00:28:42,299", "arabic": "فَقَوْلُكَ نَظَرْتُ إِلَى الشَّيْءِ لَمْ يَكُنْ ذَلِكَ إِلَّا بِالْعَيْنِ", "segs": null, "full_uz": "«Narsaga qaradim» deganingizda, bu faqat ko'z bilan bo'ladi.", "note": null},
  {"num": 406, "time": "00:28:42,299 --> 00:28:47,679", "arabic": "أَمَّا قَوْلُهُمْ إِنَّ ذَلِكَ أَحْرَى بِتَنْزِيهِ اللَّهِ عَنِ التَّجْسِيمِ", "segs": null, "full_uz": "Ularning «bu Allohni jismlashtirishdan pok bilishga ko'proq mos», degan gapiga kelsak.", "note": null},
  {"num": 407, "time": "00:28:47,679 --> 00:28:53,159", "arabic": "فَأَقُولُ نَحْنُ أَهْلَ السُّنَّةِ نُنَزِّهُ اللَّهَ كَمَا عَلَّمَنَا أَنْ نُنَزِّهَ", "segs": null, "full_uz": "Aytamanki, biz ahli sunna Allohni bizga o'rgatilgandek pok deb bilamiz.", "note": null},
  {"num": 408, "time": "00:28:53,159 --> 00:28:56,759", "arabic": "بِلَا تَعْطِيلٍ أَوْ تَشْبِيهٍ أَوْ تَجْسِيمٍ", "segs": null, "full_uz": "Inkor qilmasdan, o'xshatmasdan va jismlashtirmasdan.", "note": null},
  {"num": 409, "time": "00:28:56,759 --> 00:29:00,319", "arabic": "فَنَحْنُ نُثْبِتُ لِلَّهِ مَا أَثْبَتَهُ لِنَفْسِهِ", "segs": null, "full_uz": "Biz Allohga U O'zi uchun isbotlagan narsani isbotlaymiz.", "note": null},
  {"num": 410, "time": "00:29:00,319 --> 00:29:05,039", "arabic": "وَمَا أَثْبَتَهُ رَسُولُهُ مُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سُنَّتِهِ الصَّحِيحَةِ", "segs": null, "full_uz": "Va Uning elchisi Muhammad (sollallohu alayhi va sallam) o'zining sahih sunnatida isbotlagan narsani.", "note": null},
  {"num": 411, "time": "00:29:05,039 --> 00:29:09,200", "arabic": "فَلِلَّهِ الْأَمْرُ وَمَا عَلَيْنَا إِلَّا السَّمْعُ وَالطَّاعَةُ", "segs": null, "full_uz": "Ish Allohnikidir, bizga esa faqat eshitish va bo'ysunish qoladi.", "note": null},
  {"num": 412, "time": "00:29:09,200 --> 00:29:15,679", "arabic": "لِذَلِكَ فَإِنَّ حُجَجَ مَنْ أَنْكَرَ النَّظَرَ لِوَجْهِ الرَّحْمَنِ يَوْمَ الْقِيَامَةِ وَاهِيَةٌ وَبَاطِلَةٌ", "segs": null, "full_uz": "Shu sababli, qiyomat kunida Rahmonning yuziga qarashni inkor qilganlarning dalillari zaif va botildir.", "note": null},
  {"num": 413, "time": "00:29:15,679 --> 00:29:18,659", "arabic": "بِصَرِيحِ الْكِتَابِ وَالسُّنَّةِ الصَّحِيحَةِ", "segs": null, "full_uz": "Kitobning aniq matni va sahih sunnat bo'yicha.", "note": null},
  {"num": 414, "time": "00:29:18,659 --> 00:29:21,319", "arabic": "فَهِيَ تُنَاقِضُ الْآيَاتِ وَالْأَحَادِيثَ الصَّحِيحَةَ", "segs": null, "full_uz": "Ular sahih oyat va hadislarga zid keladi.", "note": null},
  {"num": 415, "time": "00:29:22,019 --> 00:29:24,599", "arabic": "وَتَمَسُّكُ هَؤُلَاءِ بِمَنْطِقِهِمُ الْفَاسِدِ", "segs": null, "full_uz": "Va bularning o'z buzuq mantig'iga yopishib olishi.", "note": null},
  {"num": 416, "time": "00:29:24,599 --> 00:29:28,599", "arabic": "سَيَضُرُّ بِهِمْ أَوَّلًا وَبِعَوَامِّ الْمُسْلِمِينَ ثَانِيًا أَكْثَرَ", "segs": null, "full_uz": "Avvalo o'zlariga, so'ngra esa musulmonlar ommasiga ko'proq zarar keltiradi.", "note": null},
  {"num": 417, "time": "00:29:28,599 --> 00:29:33,240", "arabic": "وَلَا أَحْسَبُ بَدْرًا إِلَّا ضَحِيَّةَ الْآرَاءِ الْمُنْحَرِفَةِ لِلْمُعْتَزِلَةِ", "segs": null, "full_uz": "Menimcha, Badr mu'taziliylarning noto'g'ri qarashlariga qurbon bo'lgan, xolos.", "note": null},
  {"num": 418, "time": "00:29:33,240 --> 00:29:35,599", "arabic": "وَأَمْثَالُهُمْ مِنْ أَهْلِ الْبِدَعِ وَالضَّلَالِ", "segs": null, "full_uz": "Va ularga o'xshaganlar — bid'at va adashuv ahlidan.", "note": null},
  {"num": 419, "time": "00:29:35,599 --> 00:29:41,599", "arabic": "كَلَامُكَ يُجَانِبُ الصَّوَابَ يَا ابْنَ نُوحٍ", "segs": null, "full_uz": "Gaping to'g'rilikdan chetlashgan, ey Ibn Nuh.", "note": null},
  {"num": 420, "time": "00:29:58,599 --> 00:30:09,980", "arabic": "اَلسَّلَامُ عَلَيْكُمْ", "segs": null, "full_uz": "Assalomu alaykum.", "note": null},
  {"num": 421, "time": "00:30:09,980 --> 00:30:12,159", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Va sizga ham salom va Allohning rahmati bo'lsin.", "note": null},
  {"num": 422, "time": "00:30:12,159 --> 00:30:13,879", "arabic": "أَهْلًا بِأُمِّ عَامِرٍ", "segs": null, "full_uz": "Xush kelibsiz, Umm Omir.", "note": null},
  {"num": 423, "time": "00:30:13,879 --> 00:30:16,099", "arabic": "جِئْتُكِ زَائِرَةً يَا أُمَّ أَحْمَدَ", "segs": null, "full_uz": "Sizga mehmon bo'lib keldim, Umm Ahmad.", "note": null},
  {"num": 424, "time": "00:30:16,099 --> 00:30:18,719", "arabic": "وَنِعْمَ مَنْ زَارَنَا أَيَّتُهَا الْمَرْأَةُ الطَّيِّبَةُ", "segs": null, "full_uz": "Bizga tashrif buyurgan qanday yaxshi, ey mehribon ayol.", "note": null},
  {"num": 425, "time": "00:30:18,719 --> 00:30:20,779", "arabic": "تَفَضَّلِي عَلَى الرُّحْبِ وَالسَّعَةِ", "segs": null, "full_uz": "Marhamat, xush kelibsiz.", "note": null},
  {"num": 427, "time": "00:30:34,920 --> 00:30:39,119", "arabic": "أَحْضِرْ مَا تَبَقَّى عِنْدَكَ مِنْ ثِيَابٍ", "segs": null, "full_uz": "Qolgan kiyimlarni olib kel.", "note": null},
  {"num": 428, "time": "00:30:39,119 --> 00:30:41,200", "arabic": "الَّتِي تُنَظِّفُهَا هَذِهِ الْمَفْتُونَةُ", "segs": null, "full_uz": "Ularni bu jinni tozalasin.", "note": null},
  {"num": 429, "time": "00:30:41,200 --> 00:30:43,299", "arabic": "لَا أُرِيدُهَا أَنْ تَرْتَاحَ أَبَدًا", "segs": null, "full_uz": "Uning hech qachon dam olishini xohlamayman.", "note": null},
  {"num": 430, "time": "00:30:43,299 --> 00:30:45,819", "arabic": "وَبَعْدَ أَنْ تَنْتَهِيَ مِنَ الثِّيَابِ", "segs": null, "full_uz": "Kiyimlarni tugatgandan keyin.", "note": null},
  {"num": 431, "time": "00:30:45,819 --> 00:30:49,099", "arabic": "اِجْعَلْهَا تُنَظِّفُ الْبِسَاطَ وَالسَّجَّادَ", "segs": null, "full_uz": "Uni gilam va palaslarni tozalashga majbur qil.", "note": null},
  {"num": 432, "time": "00:30:49,099 --> 00:30:50,200", "arabic": "هَلْ فَهِمْتِ؟", "segs": null, "full_uz": "Tushundingmi?", "note": null},
  {"num": 433, "time": "00:30:50,200 --> 00:30:51,400", "arabic": "فَهِمْتُ، فَهِمْتُ", "segs": null, "full_uz": "Tushundim, tushundim.", "note": null},
  {"num": 434, "time": "00:30:51,400 --> 00:30:54,200", "arabic": "وَإِيَّاكِ أَنْ تَغِيبَ عَنْ عَيْنِكِ لَحْظَةً وَاحِدَةً", "segs": null, "full_uz": "Uni bir lahzaga ham ko'zdan qochirma.", "note": null},
  {"num": 435, "time": "00:30:54,200 --> 00:30:56,400", "arabic": "فَهِيَ دَاهِيَةٌ مَاكِرَةٌ", "segs": null, "full_uz": "Chunki u ayyor va hiyla-nayrangchi.", "note": null},
  {"num": 436, "time": "00:30:56,400 --> 00:30:58,600", "arabic": "سَأَفْعَلُ يَا زُمُرُّدُ، سَأَفْعَلُ", "segs": null, "full_uz": "Shunday qilaman, Zumurrud, shunday qilaman.", "note": null},
  {"num": 437, "time": "00:30:58,600 --> 00:31:00,400", "arabic": "سَأَدْخُلُ لِأَرْتَاحَ", "segs": null, "full_uz": "Dam olish uchun ichkariga kiraman.", "note": null},
  {"num": 438, "time": "00:31:12,200 --> 00:31:16,400", "arabic": "لَقَدْ خَسِرْتِ يَا فَوْزُ سَيِّدًا لَنْ تَجِدِي مِثْلَهُ أَبَدًا", "segs": null, "full_uz": "Fawz, sen hech qachon topolmaydigan bir xo'jayinni yo'qotding.", "note": null},
  {"num": 439, "time": "00:31:17,000 --> 00:31:20,000", "arabic": "قُلْتُهَا لَكِ وَسَأُعِيدُهَا مِرَارًا", "segs": null, "full_uz": "Senga aytdim va yana-yana takrorlayman.", "note": null},
  {"num": 440, "time": "00:31:20,200 --> 00:31:24,799", "arabic": "اِقْبَلِي بِأَوَّلِ مُشْتَرٍ فَهُوَ أَفْضَلُ مِنَ الْحَيَاةِ مَعَ هَذِهِ الْمَرْأَةِ النَّكْدَاءِ", "segs": null, "full_uz": "Birinchi xaridorga rozi bo'l, bu shu badbaxt ayol bilan yashagandan yaxshiroq.", "note": null},
  {"num": 441, "time": "00:31:24,799 --> 00:31:29,640", "arabic": "أَشَدُّ مَا أَخْشَاهُ أَنْ تَفْقِدَ زَوْجَتِي صَبْرَهَا", "segs": null, "full_uz": "Eng qo'rqqanim — xotinim sabrini yo'qotishi.", "note": null},
  {"num": 442, "time": "00:31:29,640 --> 00:31:32,559", "arabic": "فَحِينَهَا سَتَتَمَنَّيْنَ الْمَوْتَ وَلَنْ تَجِدِيهِ", "segs": null, "full_uz": "O'shanda o'limni orzu qilasan-u, lekin topa olmaysan.", "note": null},
  {"num": 443, "time": "00:31:32,559 --> 00:31:37,500", "arabic": "اُدْعِي اللَّهَ أَنْ يَصْدُقَ الرَّجُلُ", "segs": null, "full_uz": "Allohga duo qilki, u kishi so'zida tursin.", "note": null},
  {"num": 444, "time": "00:31:37,500 --> 00:31:38,319", "arabic": "لَنْ يَعُودَ وَلَنْ يَعُودَ", "segs": null, "full_uz": "U qaytmaydi, qaytmaydi.", "note": null},
  {"num": 445, "time": "00:31:38,319 --> 00:31:41,480", "arabic": "وَإِنْ عَادَ فَلَنْ يَسْمَعَ مِنِّي إِلَّا مَا سَمِعَ", "segs": null, "full_uz": "Agar qaytib kelsa ham, mendan avval eshitganidan boshqasini eshitmaydi.", "note": null},
  {"num": 446, "time": "00:31:41,480 --> 00:31:43,580", "arabic": "عِنَادُكِ هَذَا سَيَقْتُلُكِ", "segs": null, "full_uz": "Bu o'jarliging seni halok qiladi.", "note": null},
  {"num": 447, "time": "00:31:43,580 --> 00:31:49,180", "arabic": "صَدِّقِينِي إِنَّ هَذَا الرَّجُلَ طَيِّبُ الْقَلْبِ وَسَيَكُونُ مَعَكِ أَرْحَمَ مِنْ زَوْجِي زُمُرُّدَ", "segs": null, "full_uz": "Ishon menga, bu kishi mehribon qalbli, u senga mening xo'jayinim Zumurruddan ko'ra ko'proq shafqat qiladi.", "note": null},
  {"num": 448, "time": "00:31:49,180 --> 00:31:52,180", "arabic": "فَكِّرِي فِي الْأَمْرِ لَنْ تَخْسَرِي شَيْئًا", "segs": null, "full_uz": "Bu haqda o'yla, hech narsa yo'qotmaysan.", "note": null},
  {"num": 449, "time": "00:32:00,180 --> 00:32:02,180", "arabic": "كَانَ اللَّهُ فِي الْعَوْنِ يَا أُمَّ أَحْمَدَ", "segs": null, "full_uz": "Alloh yordamchi bo'lsin, Umm Ahmad.", "note": null},
  {"num": 450, "time": "00:32:03,180 --> 00:32:05,180", "arabic": "إِنَّ تَكَالِيفَ الْمَعِيشَةِ أَضْحَتْ صَعْبَةً", "segs": null, "full_uz": "Turmush xarajatlari og'irlashib ketdi.", "note": null},
  {"num": 451, "time": "00:32:06,180 --> 00:32:09,180", "arabic": "رُكُودٌ فِي الْأَسْوَاقِ وَغَلَاءٌ فِي الْأَسْعَارِ", "segs": null, "full_uz": "Bozorlarda turg'unlik, narxlarda qimmatchilik.", "note": null},
  {"num": 452, "time": "00:32:09,180 --> 00:32:12,180", "arabic": "وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ", "segs": null, "full_uz": "Kuch-quvvat faqat Alloh bilandir.", "note": null},
  {"num": 453, "time": "00:32:12,180 --> 00:32:14,180", "arabic": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ", "segs": null, "full_uz": "Kuch-quvvat faqat Alloh bilandir.", "note": null},
  {"num": 454, "time": "00:32:14,180 --> 00:32:23,320", "arabic": "إِنَّ ابْنَ عَامِرٍ يَخْرُجُ كُلَّ يَوْمٍ إِلَى عَمَلِهِ فِي الدُّكَّانِ مِنْ شُرُوقِ الشَّمْسِ حَتَّى مَغِيبِهَا", "segs": null, "full_uz": "Omirning o'g'li har kuni quyosh chiqishidan botishigacha do'kondagi ishiga boradi.", "note": null},
  {"num": 455, "time": "00:32:23,320 --> 00:32:29,940", "arabic": "وَلَا يَعُودُ آخِرَ النَّهَارِ إِلَّا بِمَا لَا يَكَادُ يَسُدُّ الرَّمَقَ", "segs": null, "full_uz": "Kun oxirida esa qornini deyarli to'ydirmaydigan narsa bilan qaytadi.", "note": null},
  {"num": 456, "time": "00:32:29,940 --> 00:32:35,920", "arabic": "لِمَ لَا تَجْعَلِينَهُ يَتْرُكُ الْعَمَلَ فِي الدُّكَّانِ مُنْذُ زَمَنٍ؟", "segs": null, "full_uz": "Nega uni allaqachon do'kondagi ishni tashlashga undamaysiz?", "note": null},
  {"num": 457, "time": "00:32:35,920 --> 00:32:40,920", "arabic": "وَلِمَ يَتْرُكُ الْعَمَلَ فِي الدُّكَّانِ؟ وَمَاذَا سَيَعْمَلُ إِنْ هُوَ تَرَكَهَا؟", "segs": null, "full_uz": "Nega u do'konni tashlashi kerak? Agar tashlasa, nima ish qiladi?", "note": null},
  {"num": 458, "time": "00:32:40,920 --> 00:32:42,680", "arabic": "قُلْتُ لَهُ ذَلِكَ", "segs": null, "full_uz": "Men ham unga shunday dedim.", "note": null},
  {"num": 459, "time": "00:32:42,680 --> 00:32:48,080", "arabic": "قَالَ إِنَّهُ يُفَكِّرُ فِي إِيجَادِ عَمَلٍ آخَرَ يَدُرُّ عَلَيْهِ مَالًا", "segs": null, "full_uz": "U menga ko'proq pul keltiradigan boshqa ish topishni o'ylayotganini aytdi.", "note": null},
  {"num": 460, "time": "00:32:48,080 --> 00:32:51,820", "arabic": "لَوْلَا أَنَّهُ مَدِينٌ لَكُمْ بِأُجْرَةٍ يُحَاوِلُ سَدَادَهَا", "segs": null, "full_uz": "Agar sizlarga to'lamoqchi bo'lgan ijara qarzi bo'lmaganida.", "note": null},
  {"num": 461, "time": "00:32:51,820 --> 00:32:54,240", "arabic": "فَتَرَكَ الدُّكَّانَ مُنْذُ زَمَنٍ", "segs": null, "full_uz": "Do'konni ancha oldin tashlab ketardi.", "note": null},
  {"num": 462, "time": "00:32:54,240 --> 00:32:56,800", "arabic": "إِيهِ", "segs": null, "full_uz": "Voy.", "note": null},
  {"num": 463, "time": "00:32:56,800 --> 00:32:59,880", "arabic": "كَانَ اللَّهُ فِي عَوْنِ الْعِبَادِ يَا أُمَّ عَامِرٍ", "segs": null, "full_uz": "Alloh bandalarga yordamchi bo'lsin, Umm Omir.", "note": null},
  {"num": 464, "time": "00:32:59,880 --> 00:33:05,039", "arabic": "أَخْبَرَنِي عَامِرٌ أَنَّ رَجُلًا جَاءَ إِلَيْهِ يُرِيدُ شِرَاءَ الدُّكَّانِ", "segs": null, "full_uz": "Omir menga bir kishi kelib, do'konni sotib olmoqchi ekanini aytdi.", "note": null},
  {"num": 465, "time": "00:33:05,039 --> 00:33:06,960", "arabic": "يَحْسَبُهَا مِلْكًا لَهُ", "segs": null, "full_uz": "Uni o'ziniki deb o'ylagan.", "note": null},
  {"num": 466, "time": "00:33:06,960 --> 00:33:11,799", "arabic": "لَكِنَّهُ قَالَ لَهُ إِنَّهَا مِلْكٌ لِابْنِ حَنْبَلٍ", "segs": null, "full_uz": "Lekin u unga bu Ibn Hanbalning mulki ekanini aytgan.", "note": null},
  {"num": 467, "time": "00:33:11,799 --> 00:33:16,680", "arabic": "هَلْ عَرَضَ عَلَيْكُمْ أَحَدٌ شِرَاءَ الدُّكَّانِ؟", "segs": null, "full_uz": "Sizga do'konni sotib olishni birov taklif qildimi?", "note": null},
  {"num": 468, "time": "00:33:16,680 --> 00:33:20,180", "arabic": "لَا لَا لَمْ أَسْمَعْ هَذَا الْكَلَامَ إِلَّا مِنْكِ الْآنَ", "segs": null, "full_uz": "Yo'q, yo'q, bu gapni faqat hozir sizdan eshityapman.", "note": null},
  {"num": 469, "time": "00:33:20,180 --> 00:33:27,319", "arabic": "رُبَّمَا كَانَ قَدْ عَرَضَ الْأَمْرَ عَلَى وَلَدِكِ أَحْمَدَ حَفِظَهُ اللَّهُ وَنَسِيَ أَنْ يُخْبِرَكِ", "segs": null, "full_uz": "Balki bu masalani o'g'lingiz Ahmadga — Alloh uni asrasin — taklif qilgandir-u, sizga aytishni unutgandir.", "note": null},
  {"num": 470, "time": "00:33:36,960 --> 00:33:40,680", "arabic": "لَا أَظُنُّ أَنَّ وَلَدِي أَحْمَدَ يَرْغَبُ فِي بَيْعِ الدُّكَّانِ", "segs": null, "full_uz": "O'g'lim Ahmad do'konni sotishni xohlaydi deb o'ylamayman.", "note": null},
  {"num": 471, "time": "00:33:40,680 --> 00:33:44,460", "arabic": "وَمَا الَّذِي يَمْنَعُهُ؟", "segs": null, "full_uz": "Uni nima to'sib turibdi?", "note": null},
  {"num": 472, "time": "00:33:44,460 --> 00:33:47,480", "arabic": "إِنَّهَا لَا تَكَادُ تَعُودُ عَلَيْكُمْ بِشَيْءٍ يُذْكَرُ", "segs": null, "full_uz": "U sizlarga deyarli hech qanday foyda keltirmayapti.", "note": null},
  {"num": 473, "time": "00:33:47,480 --> 00:33:56,519", "arabic": "إِنَّ الْأَلْفَ دِرْهَمٍ كَفِيلَةٌ بِمُسَاعَدَتِكُمْ مُسَاعَدَةً عَظِيمَةً", "segs": null, "full_uz": "Ming dirham sizlarga katta yordam bera oladi.", "note": null},
  {"num": 474, "time": "00:33:56,519 --> 00:34:01,740", "arabic": "فَلَوِ اتَّجَرَ بِهَا أَحْمَدُ لَعَادَتْ عَلَيْهِ بِأَرْبَاحٍ مُضَاعَفَةٍ", "segs": null, "full_uz": "Agar Ahmad u bilan savdo qilsa, unga ikki barobar foyda keltiradi.", "note": null},
  {"num": 475, "time": "00:34:01,740 --> 00:34:05,360", "arabic": "فِي غُضُونِ عَامٍ الْأَلْفُ سَتُصْبِحُ أَلْفَيْنِ", "segs": null, "full_uz": "Bir yil ichida ming ikki mingga aylanadi.", "note": null},
  {"num": 476, "time": "00:34:05,359 --> 00:34:06,959", "arabic": "وَالْأَلْفَانِ خَمْسَةٌ", "segs": null, "full_uz": "Ikki ming esa beshga.", "note": null},
  {"num": 477, "time": "00:34:06,959 --> 00:34:12,359", "arabic": "أَيَّ أَلْفِ دِرْهَمٍ تَقْصِدِينَ؟", "segs": null, "full_uz": "Qaysi ming dirhamni nazarda tutyapsiz?", "note": null},
  {"num": 478, "time": "00:34:12,980 --> 00:34:16,579", "arabic": "اَلْأَلْفَ دِرْهَمٍ الَّتِي عَرَضَهَا الرَّجُلُ ثَمَنًا لِشِرَاءِ الدُّكَّانِ", "segs": null, "full_uz": "O'sha kishi do'konni sotib olish uchun taklif qilgan ming dirhamni.", "note": null},
  {"num": 484, "time": "00:35:14,900 --> 00:35:19,039", "arabic": "أَسْعَدَتْنَا زِيَارَتُكِ يَا أُمَّ عَامِرٍ", "segs": null, "full_uz": "Tashrifingiz bizni xursand qildi, Umm Omir.", "note": null},
  {"num": 485, "time": "00:35:19,039 --> 00:35:21,360", "arabic": "لَا تَبْخَلِي عَلَيْنَا بِزِيَارَةٍ أُخْرَى", "segs": null, "full_uz": "Yana tashrif buyurishni ayamang.", "note": null},
  {"num": 486, "time": "00:35:21,940 --> 00:35:23,860", "arabic": "زَادَكِ اللَّهُ شَرَفًا يَا صَفِيَّةُ", "segs": null, "full_uz": "Alloh sizga shon-shuhrat ziyoda qilsin, Safiya.", "note": null},
  {"num": 487, "time": "00:35:23,860 --> 00:35:26,180", "arabic": "وَدِدْتُ لَوْ أَزُورُكِ كُلَّ يَوْمٍ", "segs": null, "full_uz": "Har kuni sizga tashrif buyurishni orzu qilardim.", "note": null},
  {"num": 488, "time": "00:35:26,180 --> 00:35:29,140", "arabic": "وَلَكِنْ كَمَا تَرَيْنَ مَهَامُّ عَظِيمَةٌ تَشْغَلُنِي", "segs": null, "full_uz": "Lekin, ko'rib turganingizdek, katta ishlar meni band qilib qo'ygan.", "note": null},
  {"num": 489, "time": "00:35:29,140 --> 00:35:31,760", "arabic": "أَطَالَ اللَّهُ عُمْرَكِ يَا أُمَّ عَامِرٍ", "segs": null, "full_uz": "Alloh umringizni uzun qilsin, Umm Omir.", "note": null},
  {"num": 490, "time": "00:35:31,760 --> 00:35:32,920", "arabic": "أَرَاكِ بِخَيْرٍ", "segs": null, "full_uz": "Sizni sog'-salomat ko'raman.", "note": null},
  {"num": 491, "time": "00:35:32,920 --> 00:35:35,039", "arabic": "وَأَنْتِ بِخَيْرٍ بِأَمَانِ اللَّهِ", "segs": null, "full_uz": "Siz ham sog'-salomat bo'ling, Alloh amonatida.", "note": null},
  {"num": 492, "time": "00:35:35,039 --> 00:35:36,599", "arabic": "مَعَ السَّلَامَةِ", "segs": null, "full_uz": "Xayr, omon bo'ling.", "note": null},
  {"num": 494, "time": "00:36:32,920 --> 00:36:44,340", "arabic": "سُبْحَانَ اللَّهِ", "segs": null, "full_uz": "Subhanalloh.", "note": null},
  {"num": 495, "time": "00:36:44,340 --> 00:36:47,300", "arabic": "غَرِيبٌ أَمْرُ السَّلَاطِينِ", "segs": null, "full_uz": "Sultonlarning ishi g'alati.", "note": null},
  {"num": 496, "time": "00:36:47,300 --> 00:36:50,820", "arabic": "إِذَا أَرَادُوا يَرْمُونَكَ فِي الْقَاعِ", "segs": null, "full_uz": "Xohlashsa, seni tag-tubga otib yuboradilar.", "note": null},
  {"num": 497, "time": "00:36:50,820 --> 00:36:55,500", "arabic": "وَإِذَا أَرَادُوا يَرْفَعُونَكَ لِنَعِيمِ الدُّنْيَا", "segs": null, "full_uz": "Va xohlashsa, seni dunyo ne'matlariga ko'targizadilar.", "note": null},
  {"num": 498, "time": "00:36:55,500 --> 00:36:57,920", "arabic": "مِنْ حَيْثُ لَا تَتَوَقَّعُ", "segs": null, "full_uz": "Kutmagan joyingdan.", "note": null},
  {"num": 499, "time": "00:37:02,920 --> 00:37:21,840", "arabic": "لَمْ تُخْبِرْنِي أَنَّ الدُّكَّانَ جَاءَهَا مُشْتَرٍ", "segs": null, "full_uz": "Do'konga xaridor kelganini menga aytmagansan.", "note": null},
  {"num": 500, "time": "00:37:21,840 --> 00:37:26,200", "arabic": "لَمْ أَرَ الْأَمْرَ مُهِمًّا فَلَمْ أُرِدْ أَنْ تَشْغَلِي بَالَكِ بِهِ", "segs": null, "full_uz": "Buni muhim deb bilmadim, shuning uchun sizni bezovta qilmoqchi emas edim.", "note": null},
  {"num": 501, "time": "00:37:26,200 --> 00:37:30,920", "arabic": "وَكَيْفَ لَا يَكُونُ مُهِمًّا وَالرَّجُلُ قَدْ دَفَعَ لَكَ أَلْفَ دِرْهَمٍ", "segs": null, "full_uz": "U kishi senga ming dirham to'lagan bo'lsa, bu qanday muhim bo'lmaydi?", "note": null},
  {"num": 502, "time": "00:37:30,920 --> 00:37:34,920", "arabic": "مَنْ أَخْبَرَكِ بِذَلِكَ؟", "segs": null, "full_uz": "Senga buni kim aytdi?", "note": null},
  {"num": 503, "time": "00:37:35,559 --> 00:37:38,960", "arabic": "إِذَنْ أَخْبَرَتْكِ أُمُّ عَامِرٍ", "segs": null, "full_uz": "Demak, senga Umm Omir aytgan.", "note": null},
  {"num": 504, "time": "00:37:38,960 --> 00:37:41,079", "arabic": "أَجَلْ هِيَ مَنْ أَخْبَرَتْنِي", "segs": null, "full_uz": "Ha, menga aytgan aynan o'zi.", "note": null},
  {"num": 505, "time": "00:37:41,079 --> 00:37:43,880", "arabic": "وَلَكِنْ دَعْكَ مِنْ أُمِّ عَامِرٍ وَابْنِهَا وَقُلْ لِي", "segs": null, "full_uz": "Lekin Umm Omir va uning o'g'lini qo'yib tur-da, ayt-chi.", "note": null},
  {"num": 506, "time": "00:37:43,880 --> 00:37:48,280", "arabic": "أَصَحِيحٌ أَنَّ الرَّجُلَ قَدْ دَفَعَ لَكَ أَلْفَ دِرْهَمٍ ثَمَنًا لِلدُّكَّانِ؟", "segs": null, "full_uz": "U kishi do'kon uchun senga rostdan ham ming dirham to'ladimi?", "note": null},
  {"num": 507, "time": "00:37:48,280 --> 00:37:49,840", "arabic": "هَذَا صَحِيحٌ يَا أُمِّي", "segs": null, "full_uz": "Rost, onajon.", "note": null},
  {"num": 508, "time": "00:37:49,840 --> 00:37:52,039", "arabic": "وَلَكِنَّ دُكَّانَ أَبِي لَيْسَتْ لِلْبَيْعِ", "segs": null, "full_uz": "Lekin otamning do'koni sotuvga emas.", "note": null},
  {"num": 509, "time": "00:37:52,039 --> 00:37:58,099", "arabic": "أَيُفَرِّطُ أَحَدٌ فِي مَوْرِدِ رِزْقِهِ لِقَاءَ نُقُودٍ مَا أَنْ يَحُولَ عَلَيْهَا الْحَوْلُ حَتَّى تَكُونَ قَدْ نَفِدَتْ؟", "segs": [{"ar": "أَيُفَرِّطُ أَحَدٌ فِي مَوْرِدِ رِزْقِهِ", "uz": "kimdir o'z rizq manbaidan voz kecharmidi"}, {"ar": "لِقَاءَ نُقُودٍ مَا أَنْ يَحُولَ عَلَيْهَا الْحَوْلُ حَتَّى تَكُونَ قَدْ نَفِدَتْ؟", "uz": "bir yil o'tar-o'tmas tugab qoladigan pul evaziga?"}], "full_uz": "Bir yil o'tar-o'tmas tugab qoladigan pul evaziga kimdir o'z rizq manbaidan voz kecharmidi?", "note": null},
  {"num": 510, "time": "00:37:58,099 --> 00:37:58,920", "arabic": "أَلْفُ دِرْهَمٍ", "segs": null, "full_uz": "Ming dirham.", "note": null},
  {"num": 511, "time": "00:37:58,920 --> 00:38:03,619", "arabic": "إِنْ وَظَّفْتَهَا فِي تِجَارَةٍ رَابِحَةٍ فَكَيْفَ لَهَا أَنْ تَنْفَدَ؟", "segs": null, "full_uz": "Agar uni foydali savdoga qo'ysang, u qanday tugaydi?", "note": null},
  {"num": 512, "time": "00:38:03,619 --> 00:38:06,340", "arabic": "هَذَا لَوْ كُنْتُ أَفْهَمُ فِي التِّجَارَةِ يَا أُمِّي", "segs": null, "full_uz": "Bu, agar savdodan tushunsam bo'lardi, onajon.", "note": null},
  {"num": 513, "time": "00:38:06,340 --> 00:38:08,599", "arabic": "فَمَا بَالُكِ وَأَنَا لَا أَفْهَمُ فِي أُصُولِهَا شَيْئًا", "segs": null, "full_uz": "Uning asoslaridan zarracha tushunmasam-chi?", "note": null},
  {"num": 514, "time": "00:38:08,599 --> 00:38:10,880", "arabic": "فَقَدْ أَنْفَقْتُ عُمْرِي فِي حَلَقَاتِ الدَّرْسِ", "segs": null, "full_uz": "Umrimni dars halqalarida o'tkazdim.", "note": null},
  {"num": 515, "time": "00:38:10,880 --> 00:38:14,059", "arabic": "إِنَّ لِلتِّجَارَةِ أَهْلَهَا وَأَنَا لَسْتُ وَاحِدًا مِنْهُمْ", "segs": null, "full_uz": "Savdoning o'z ahli bor, men esa ulardan biri emasman.", "note": null},
  {"num": 516, "time": "00:38:14,059 --> 00:38:17,460", "arabic": "اَلرَّأْيُ رَأْيُكَ يَا وَلَدِي فَأَنْتَ رَجُلُ الْبَيْتِ", "segs": null, "full_uz": "Fikr — sening fikring, o'g'lim, chunki sen uy egasisan.", "note": null},
  {"num": 517, "time": "00:38:17,460 --> 00:38:21,740", "arabic": "وَأَنَا لَنْ أُقْدِمَ عَلَى أَمْرٍ أَنْتَ لَسْتَ بِرَادٍّ عَنْهُ", "segs": null, "full_uz": "Va men sen rozi bo'lmagan bir ishga qadam qo'ymayman.", "note": null},
  {"num": 518, "time": "00:38:21,740 --> 00:38:26,119", "arabic": "وَلَكِنْ هَا نَحْنُ نَتَنَاقَشُ مِنْ أَجْلِ أَنْ نَصِلَ إِلَى الرَّأْيِ الصَّوَابِ", "segs": null, "full_uz": "Lekin mana, biz to'g'ri fikrga kelish uchun muhokama qilyapmiz.", "note": null},
  {"num": 519, "time": "00:38:26,119 --> 00:38:28,639", "arabic": "وَأَنْتَ لَيْسَ لَكَ مِنَ الدُّكَّانِ سِوَى الِاسْمِ", "segs": null, "full_uz": "Senda do'kondan faqat nomigina qolgan.", "note": null},
  {"num": 520, "time": "00:38:28,639 --> 00:38:32,079", "arabic": "فَمُنْذُ أَشْهُرٍ لَمْ تَعُدْ عَلَيْكَ بِدِرْهَمٍ وَاحِدٍ", "segs": null, "full_uz": "Necha oydan beri senga bir dirham ham keltirmayapti.", "note": null},
  {"num": 521, "time": "00:38:32,079 --> 00:38:34,559", "arabic": "وَأَنْتَ عَلَى الرَّغْمِ مِنِ اشْتِغَالِكَ بِالْعِلْمِ", "segs": null, "full_uz": "Sen ilm bilan mashg'ul bo'lishingga qaramay.", "note": null},
  {"num": 522, "time": "00:38:34,559 --> 00:38:38,559", "arabic": "تُضْطَرُّ أَحْيَانًا إِلَى الْعَمَلِ مِنْ أَجْلِ أَنْ تُؤَمِّنَ لَنَا نَفَقَةَ الْبَيْتِ", "segs": null, "full_uz": "Ba'zan uyimizning xarajatini ta'minlash uchun ishlashga majbur bo'lasan.", "note": null},
  {"num": 523, "time": "00:38:38,559 --> 00:38:42,059", "arabic": "وَغَدًا إِنْ تَرَكَ الْإِسْكَافِيُّ الدُّكَّانَ", "segs": null, "full_uz": "Ertaga etikdo'z do'konni tashlab ketsa.", "note": null},
  {"num": 524, "time": "00:38:42,059 --> 00:38:44,119", "arabic": "فَسَتَبْحَثُ عَنْ مُكْتَرٍ آخَرَ", "segs": null, "full_uz": "Boshqa ijarachi qidirasan.", "note": null},
  {"num": 525, "time": "00:38:44,119 --> 00:38:47,900", "arabic": "رُبَّمَا تَجِدُهُ فِي يَوْمٍ وَرُبَّمَا لَا تَجِدُهُ فِي سَنَةٍ", "segs": null, "full_uz": "Balki bir kunda topasan, balki bir yilda ham topolmaysan.", "note": null},
  {"num": 526, "time": "00:38:47,900 --> 00:38:50,639", "arabic": "فَلِمَاذَا هَذِهِ الْمَشَقَّةُ يَا بُنَيَّ؟", "segs": null, "full_uz": "Nega bunday mashaqqat, o'g'lim?", "note": null},
  {"num": 527, "time": "00:38:51,359 --> 00:38:54,279", "arabic": "وَأَنَا لَنْ أَسْمَحَ لَكَ بِالْعَوْدَةِ إِلَى الْعَمَلِ", "segs": null, "full_uz": "Men senga ishga qaytishga ruxsat bermayman.", "note": null},
  {"num": 528, "time": "00:38:54,279 --> 00:38:56,639", "arabic": "وَالِانْشِغَالِ عَنِ الْعِلْمِ أَبَدًا", "segs": null, "full_uz": "Va ilmdan chalg'ishga aslo.", "note": null},
  {"num": 529, "time": "00:38:56,639 --> 00:39:01,359", "arabic": "أَمَّا قَوْلُكِ إِنَّ الدُّكَّانَ لَمْ تَعُدْ عَلَيْنَا بِدِرْهَمٍ وَاحِدٍ مُنْذُ أَشْهُرٍ", "segs": null, "full_uz": "Necha oydan beri do'kon bizga bir dirham ham keltirmagan, degan gapingizga kelsak.", "note": null},
  {"num": 530, "time": "00:39:01,359 --> 00:39:02,859", "arabic": "فَذَلِكَ صَحِيحٌ", "segs": null, "full_uz": "Bu rost.", "note": null},
  {"num": 531, "time": "00:39:02,859 --> 00:39:05,920", "arabic": "لِأَنَّنِي رَأَيْتُ إِنْظَارَ عَامِرٍ فِي عُسْرَتِهِ", "segs": null, "full_uz": "Chunki men Omirning qiynalganini ko'rib, unga muhlat berishni to'g'ri deb bildim.", "note": null},
  {"num": 532, "time": "00:39:05,920 --> 00:39:11,679", "arabic": "وَأَخْشَى أَنَّهُ يُمَاطِلُ فِي دَفْعِ إِجْرَةِ الدُّكَّانِ لِغَرَضٍ فِي نَفْسِهِ يُخْفِيهِ", "segs": null, "full_uz": "Lekin qo'rqamanki, u yashirin bir maqsad bilan do'kon ijarasini to'lashni cho'zayapti.", "note": null},
  {"num": 533, "time": "00:39:11,679 --> 00:39:14,179", "arabic": "وَيَدْفَعُنَا دَفْعًا لِبَيْعِهِ", "segs": null, "full_uz": "Va bizni uni sotishga majburlamoqchi.", "note": null},
  {"num": 534, "time": "00:39:14,179 --> 00:39:18,639", "arabic": "وَلَكِنْ إِنْ أَرَدْتِ بَيْعَ الدُّكَّانِ فَلَنْ أُخَالِفَ أَمْرَكِ", "segs": null, "full_uz": "Lekin agar do'konni sotishni xohlasangiz, gapingizga qarshi chiqmayman.", "note": null},
  {"num": 535, "time": "00:39:18,639 --> 00:39:22,319", "arabic": "أَمَّا إِذَا أَرَدْتِ رَأْيِي فَأَنَا لَا أُوَافِقُ أَبَدًا عَلَى بَيْعِهِ", "segs": null, "full_uz": "Lekin mening fikrimni xohlasangiz, uni sotishga aslo rozi emasman.", "note": null},
  {"num": 536, "time": "00:39:22,319 --> 00:39:23,859", "arabic": "وَالْقَرَارُ قَرَارُكِ", "segs": null, "full_uz": "Qaror esa — sizniki.", "note": null},
  {"num": 537, "time": "00:39:23,860 --> 00:39:28,500", "arabic": "وَالْآنَ ائْذَنِي لِي فَلَدَيَّ أَمْرٌ مُهِمٌّ يَجِبُ أَنْ أَقْضِيَهُ", "segs": null, "full_uz": "Endi menga ijozat bering, muhim ishim bor, uni bajarishim kerak.", "note": null},
  {"num": 538, "time": "00:39:28,500 --> 00:39:31,860", "arabic": "كَمَا تَرَى يَا وَلَدِي رَفَقَتْكَ السَّلَامَةُ", "segs": null, "full_uz": "Ko'rganingdek, o'g'lim, senga omonlik hamroh bo'lsin.", "note": null},
  {"num": 539, "time": "00:39:49,860 --> 00:39:51,099", "arabic": "اَلسَّلَامُ عَلَيْكُمْ", "segs": null, "full_uz": "Assalomu alaykum.", "note": null},
  {"num": 540, "time": "00:39:51,099 --> 00:39:54,139", "arabic": "وَعَلَيْكُمُ السَّلَامُ يَا أَبَا عَبْدِ اللَّهِ، تَفَضَّلْ", "segs": null, "full_uz": "Va sizga ham salom, Abu Abdulloh, marhamat.", "note": null},
  {"num": 541, "time": "00:39:54,139 --> 00:40:00,219", "arabic": "اِسْمَعْ يَا عَامِرُ، أُرِيدُ مِنْكَ أَنْ تُكْمِلَ شَهْرَكَ فِي دُكَّانِي", "segs": null, "full_uz": "Eshit, Omir, mening do'konimdagi oyingni tugatishingni xohlayman.", "note": null},
  {"num": 542, "time": "00:40:00,219 --> 00:40:03,139", "arabic": "ثُمَّ تَبْحَثَ لَكَ عَنْ دُكَّانٍ أُخْرَى تَسْتَأْجِرُهَا", "segs": null, "full_uz": "So'ngra o'zingga ijaraga oladigan boshqa do'kon qidirasan.", "note": null},
  {"num": 543, "time": "00:40:03,139 --> 00:40:05,319", "arabic": "مَاذَا؟", "segs": null, "full_uz": "Nima?", "note": null},
  {"num": 544, "time": "00:40:05,319 --> 00:40:08,539", "arabic": "أَظُنُّهُ قَدْ قَرَعَ سَمْعَكَ مَا قُلْتُ، وَسَأُعِيدُهَا ثَانِيَةً", "segs": null, "full_uz": "Menimcha, aytganim qulog'ingga yetdi, baribir yana takrorlayman.", "note": null},
  {"num": 545, "time": "00:40:08,539 --> 00:40:12,119", "arabic": "أَكْمِلْ شَهْرَكَ فِي دُكَّانِي وَغَادِرْهُ بِمَعْرُوفٍ", "segs": null, "full_uz": "Do'konimdagi oyingni tugat va yaxshilik bilan tark et.", "note": null},
  {"num": 546, "time": "00:40:12,119 --> 00:40:14,039", "arabic": "اَلسَّلَامُ عَلَيْكُمْ", "segs": null, "full_uz": "Xayr, sizga salom bo'lsin.", "note": null},
  {"num": 547, "time": "00:40:14,039 --> 00:40:16,639", "arabic": "يَا أَبَا عَبْدِ اللَّهِ، وَلَكِنْ يَا أَبَا عَبْدِ اللَّهِ", "segs": null, "full_uz": "Abu Abdulloh! Lekin, Abu Abdulloh!", "note": null},
  {"num": 548, "time": "00:40:16,639 --> 00:40:20,500", "arabic": "يَا وَيْلِي، يَا وَيْلِي، يَا وَيْلِي، يَا وَيْلَكَ يَا عَامِرُ", "segs": null, "full_uz": "Voy holimga, voy holimga, voy holimga, voy holingga, Omir!", "note": null},
  {"num": 549, "time": "00:40:20,500 --> 00:40:23,320", "arabic": "يَا وَيْلِي زَوْجِي وَأُمِّي وَأَبْنَائِي", "segs": null, "full_uz": "Voy holimga, xotinim, onam va bolalarim!", "note": null},
  {"num": 550, "time": "00:40:23,320 --> 00:40:25,320", "arabic": "يَا وَيْلِي", "segs": null, "full_uz": "Voy holimga!", "note": null},
  {"num": 551, "time": "00:40:25,320 --> 00:40:26,500", "arabic": "يَا وَيْلِي", "segs": null, "full_uz": "Voy holimga!", "note": null},
  {"num": 552, "time": "00:40:26,500 --> 00:40:28,260", "arabic": "أَبُو عَبْدِ اللَّهِ", "segs": null, "full_uz": "Abu Abdulloh!", "note": null},
  {"num": 553, "time": "00:40:28,260 --> 00:40:29,400", "arabic": "يَا وَيْلِي", "segs": null, "full_uz": "Voy holimga!", "note": null},
  {"num": 554, "time": "00:40:29,400 --> 00:40:32,420", "arabic": "يَا وَيْلَكَ يَا عَامِرُ", "segs": null, "full_uz": "Voy holingga, Omir!", "note": null},
  {"num": 555, "time": "00:40:50,500 --> 00:40:57,900", "arabic": "يَا أَحْمَدُ أَنَا عَمُّكَ وَأَحْرَصُ النَّاسِ عَلَيْكَ", "segs": null, "full_uz": "Ey Ahmad, men amakingman va senga eng ko'p g'amxo'rlik qiluvchi odamman.", "note": null},
  {"num": 556, "time": "00:40:57,900 --> 00:41:00,599", "arabic": "وَأَنْتَ تُصِرُّ عَلَى حَمْلِ مَشَاغِلِ الدُّنْيَا وَحْدَكَ", "segs": null, "full_uz": "Sen esa dunyo tashvishlarini yolg'iz o'zing ko'tarishga qat'iy turibsan.", "note": null},
  {"num": 557, "time": "00:41:00,599 --> 00:41:04,400", "arabic": "لَا أَعْلَمُ لِمَاذَا لَا تَبُوحُ بِمَا يَشْغَلُ بَالَكَ؟", "segs": null, "full_uz": "Bilmayman, nega ko'nglingni band qilgan narsani aytmayapsan?", "note": null},
  {"num": 558, "time": "00:41:04,400 --> 00:41:05,460", "arabic": "أَنْتَ قُلْتَهَا يَا عَمِّ", "segs": null, "full_uz": "O'zingiz aytdingiz-ku, amaki.", "note": null},
  {"num": 559, "time": "00:41:05,460 --> 00:41:07,539", "arabic": "أَنْتَ أَقْرَبُ النَّاسِ إِلَيَّ", "segs": null, "full_uz": "Siz menga eng yaqin odamsiz.", "note": null},
  {"num": 560, "time": "00:41:07,539 --> 00:41:10,599", "arabic": "وَلَوْ كَانَ هُنَاكَ مَا تَسْتَطِيعُ أَنْ تُسَاعِدَنِي بِهِ", "segs": null, "full_uz": "Agar menga yordam bera oladigan biror narsa bo'lsa.", "note": null},
  {"num": 561, "time": "00:41:10,599 --> 00:41:12,840", "arabic": "فَلَنْ أَطْلُبَهُ إِلَّا مِنْكَ", "segs": null, "full_uz": "Uni faqat sizdan so'rayman.", "note": null},
  {"num": 562, "time": "00:41:12,840 --> 00:41:16,679", "arabic": "غَايَةُ الْأَمْرِ أَنَّ أُمِّي تُفَكِّرُ فِي بَيْعِ الدُّكَّانِ", "segs": null, "full_uz": "Gap shundaki, onam do'konni sotishni o'ylayapti.", "note": null},
  {"num": 563, "time": "00:41:16,679 --> 00:41:20,239", "arabic": "وَأَخْشَى إِنْ عَارَضْتُ رَأْيَهَا", "segs": null, "full_uz": "Va uning fikriga qarshi chiqsam.", "note": null},
  {"num": 564, "time": "00:41:20,239 --> 00:41:21,980", "arabic": "أَكُونُ قَدْ عَقَقْتُهَا", "segs": null, "full_uz": "Unga oqibatsizlik qilgan bo'laman.", "note": null},
  {"num": 565, "time": "00:41:21,980 --> 00:41:23,919", "arabic": "إِنْ أَرَدْتَ", "segs": null, "full_uz": "Agar xohlasang.", "note": null},
  {"num": 566, "time": "00:41:23,919 --> 00:41:26,559", "arabic": "كَلَّمْتُهَا وَأَقْنَعْتُهَا بِعَدَمِ بَيْعِهَا", "segs": null, "full_uz": "Men u bilan gaplashib, sotmaslikka ko'ndirardim.", "note": null},
  {"num": 567, "time": "00:41:26,559 --> 00:41:27,019", "arabic": "لَا لَا", "segs": null, "full_uz": "Yo'q, yo'q.", "note": null},
  {"num": 568, "time": "00:41:27,019 --> 00:41:29,599", "arabic": "هُوَ رَأْيُهَا وَقَرَارُهَا", "segs": null, "full_uz": "Bu uning fikri va qarori.", "note": null},
  {"num": 569, "time": "00:41:29,599 --> 00:41:31,319", "arabic": "وَلَنْ أُخَالِفَهَا", "segs": null, "full_uz": "Va men unga qarshi chiqmayman.", "note": null},
  {"num": 570, "time": "00:41:31,319 --> 00:41:33,819", "arabic": "طَرَدُونِي مِنَ الدُّكَّانِ", "segs": null, "full_uz": "Meni do'kondan haydashdi.", "note": null},
  {"num": 571, "time": "00:41:33,819 --> 00:41:36,399", "arabic": "طَارَتْ أَحْلَامِي", "segs": null, "full_uz": "Orzularim uchib ketdi.", "note": null},
  {"num": 572, "time": "00:41:36,399 --> 00:41:39,099", "arabic": "هَذَا مَا لَمْ تَحْسِبْ حِسَابَهُ يَا عَامِرُ", "segs": null, "full_uz": "Bu sen hisobga olmagan narsa edi, Omir.", "note": null},
  {"num": 574, "time": "00:41:40,519 --> 00:41:42,899", "arabic": "مَاذَا سَيَفْعَلُ لَكَ صُهَيْبٌ هَذَا؟", "segs": null, "full_uz": "Bu Suhayb senga nima qila oladi?", "note": null},
  {"num": 575, "time": "00:41:42,900 --> 00:41:47,099", "arabic": "سُحْقًا لِلطَّمَعِ", "segs": null, "full_uz": "Ochko'zlikka la'nat!", "note": null},
  {"num": 577, "time": "00:41:49,139 --> 00:41:50,579", "arabic": "أَلَا تَجْلِسُ يَا رَجُلُ؟", "segs": null, "full_uz": "O'tirmaysanmi, odam bola?", "note": null},
  {"num": 578, "time": "00:41:50,579 --> 00:41:52,500", "arabic": "وَتَدَعَنَا نُفَكِّرُ بِهُدُوءٍ", "segs": null, "full_uz": "Va bizga xotirjam o'ylashga imkon bermaysanmi?", "note": null},
  {"num": 579, "time": "00:41:52,500 --> 00:41:56,139", "arabic": "اِجْلِسْ وَبِهُدُوءٍ", "segs": null, "full_uz": "O'tir, xotirjam bo'l.", "note": null},
  {"num": 580, "time": "00:41:56,139 --> 00:41:56,820", "arabic": "لَا تَقْلَقِي", "segs": null, "full_uz": "Xavotir olma.", "note": null},
  {"num": 581, "time": "00:41:56,820 --> 00:41:58,260", "arabic": "غَدًا سَنَجْلِسُ مَعًا", "segs": null, "full_uz": "Ertaga birga o'tiramiz.", "note": null},
  {"num": 582, "time": "00:41:58,260 --> 00:42:00,280", "arabic": "نُحْصِي ذَرَّاتِ تُرَابِ أَرْضِ بَغْدَادَ", "segs": null, "full_uz": "Bag'dod yerining tuproq zarralarini sanaymiz.", "note": "Kinoya (kesatiq) ma'nosida ishlatilgan ibora — juda batafsil va uzoq hisob-kitob degan ma'noda."},
  {"num": 583, "time": "00:42:00,280 --> 00:42:02,220", "arabic": "بَعْدَ أَنْ بَاعَ أَحْمَدُ دُكَّانَهُ", "segs": null, "full_uz": "Ahmad do'konini sotgandan keyin.", "note": null},
  {"num": 584, "time": "00:42:02,220 --> 00:42:03,440", "arabic": "لَا تَقْلَقِي", "segs": null, "full_uz": "Xavotir olma.", "note": null},
  {"num": 585, "time": "00:42:03,440 --> 00:42:05,519", "arabic": "كَفَاكِ عَوِيلًا كَالنِّسَاءِ", "segs": null, "full_uz": "Ayollardek yig'lab-siqtashni bas qil.", "note": null},
  {"num": 586, "time": "00:42:05,519 --> 00:42:07,460", "arabic": "اِجْلِسْ أَيُّهَا الْأَحْمَقُ", "segs": null, "full_uz": "O'tir, ey ahmoq.", "note": null},
  {"num": 587, "time": "00:42:07,460 --> 00:42:08,980", "arabic": "وَدَعْنِي أُفَكِّرْ لَكَ فِي حَلٍّ", "segs": null, "full_uz": "Va menga sen uchun yechim o'ylab topishga imkon ber.", "note": null}
];
if (typeof module !== "undefined" && module.exports) {
  module.exports = lessons;
}
